window.DCP_INDEX=[{"t":"Home","k":"Page","u":"index.html","s":""},{"t":"The policy","k":"Page","u":"dam.html","s":""},{"t":"Governance","k":"Page","u":"governance.html","s":""},{"t":"Cataloguing","k":"Page","u":"cataloguing.html","s":""},{"t":"Quality","k":"Page","u":"quality.html","s":""},{"t":"Sectors","k":"Page","u":"sectors.html","s":""},{"t":"Joined up","k":"Page","u":"together.html","s":""},{"t":"Delivery and change","k":"Page","u":"change.html","s":""},{"t":"Capability playbooks","k":"Page","u":"capabilities.html","s":""},{"t":"Capability model","k":"Page","u":"capability-model.html","s":""},{"t":"Knowledge areas","k":"Page","u":"areas.html","s":""},{"t":"Perspectives","k":"Page","u":"perspectives.html","s":""},{"t":"Working together","k":"Page","u":"community.html","s":""},{"t":"Professions and skills","k":"Page","u":"professions.html","s":""},{"t":"Tools and interoperability","k":"Page","u":"tooling.html","s":""},{"t":"Boards and networks","k":"Page","u":"bodies.html","s":""},{"t":"Your role","k":"Page","u":"personas.html","s":""},{"t":"New or leading","k":"Page","u":"leading.html","s":""},{"t":"Data portals compass","k":"Page","u":"compass/index.html","s":""},{"t":"Asset governance explorer","k":"Page","u":"explorer/index.html","s":""},{"t":"Learning","k":"Page","u":"learning.html","s":""},{"t":"Library","k":"Page","u":"library.html","s":""},{"t":"Knowledge","k":"Page","u":"knowledge.html","s":""},{"t":"Inclusion","k":"Page","u":"inclusion.html","s":""},{"t":"About","k":"Page","u":"about.html","s":""},{"t":"Contact form","k":"Page","u":"contact.html","s":"Ask a question, report a problem"},{"t":"Governance step 1: Mandate","k":"Data governance step","u":"governance.html#gov-mandate","s":"Establish the authority everything else operates under. Confirm the sponsor (the CDO, SIRO or equivalent) who will chair or co-sign the charter. Draft a one-pag"},{"t":"Governance step 2: Frame","k":"Data governance step","u":"governance.html#gov-frame","s":"Assemble a proportionate rulebook to make decisions against. List every data policy and standard already in force, however informal. Compare it with the core ar"},{"t":"Governance step 3: Assign","k":"Data governance step","u":"governance.html#gov-assign","s":"Put a named, accountable owner and an active steward against every critical data asset. Choose your ownership option - IAO model, data ownership model or hybrid"},{"t":"Governance step 4: Operate","k":"Data governance step","u":"governance.html#gov-operate","s":"Make governance visible day to day. Set the board's cadence (monthly, at least quarterly) and publish the calendar. Keep a decision log - what, who, why, when a"},{"t":"Governance step 5: Assure","k":"Data governance step","u":"governance.html#gov-assure","s":"Prove it works and feed the lessons back into the mandate. Re-run the data maturity self-assessment. Compile measures from the live registers - owner coverage, "},{"t":"Governance charter","k":"Data governance template","u":"governance.html#T-GOV-1","s":"Purpose Scope and exclusions Authority and sponsor Membership Decision rights Review cadence Sign-off (role and date)"},{"t":"Data ownership register entry","k":"Data governance template","u":"governance.html#T-GOV-2","s":"Asset identifier Asset title Ownership option (IAO, data owner or hybrid) Data owner (role) Information asset owner (role) Data steward (role) Data custodian (r"},{"t":"Decision log entry","k":"Data governance template","u":"governance.html#T-GOV-3","s":"Decision ID Date Decision Decided by (role or forum) Rationale Assets affected Review trigger"},{"t":"Exception register entry","k":"Data governance template","u":"governance.html#T-GOV-4","s":"Exception ID Policy deviated from Rationale Owner (role) Risk accepted by (role) Start date Expiry date Review outcome"},{"t":"Day-to-day management workbook","k":"Data governance template","u":"governance.html#T-GOV-5","s":"Risks: Risk ID Risks: Date raised Risks: Description Risks: Cause Risks: Effect Risks: Likelihood (1-5) Risks: Impact (1-5) Risks: Score Risks: Owner (role) Ris"},{"t":"Data sharing agreement","k":"Data governance template","u":"governance.html#T-GOV-6","s":"Agreement reference Parties Controller at each stage, including after sharing Data protection officer or responsible contact for each party (role) Purpose and s"},{"t":"Cataloguing step 1: Mobilise","k":"Data cataloguing step","u":"cataloguing.html#cat-mobilise","s":"Have a named lead and a coordinating team before identification starts. The CDO (or most senior data official) leads and appoints a coordinating team or person."},{"t":"Cataloguing step 2: Discover candidates","k":"Data cataloguing step","u":"cataloguing.html#cat-discover","s":"Build a long list of data other organisations depend on. Start from what you already have - data catalogues, information asset registers and registers of data s"},{"t":"Cataloguing step 3: Test and designate","k":"Data cataloguing step","u":"cataloguing.html#cat-designate","s":"Decide which candidates are critical data assets, and draw each asset's boundary. Apply the policy's scope tests - classified OFFICIAL, meets the critical data "},{"t":"Cataloguing step 4: Confirm ownership","k":"Data cataloguing step","u":"cataloguing.html#cat-own","s":"Every designated asset has a named, accountable owner before it is described. Confirm the owner (data owner or IAO) and steward for each asset with the governan"},{"t":"Cataloguing step 5: Describe","k":"Data cataloguing step","u":"cataloguing.html#cat-describe","s":"Describe each asset well enough for someone outside your team to find, understand and judge it. Record the properties in the metadata guidance (see the metadata"},{"t":"Cataloguing step 6: Catalogue and expose","k":"Data cataloguing step","u":"cataloguing.html#cat-publish","s":"Keep the record in your catalogue in a form others can harvest. Store each record in the organisation's catalogue, or an asset register where no catalogue exist"},{"t":"Cataloguing step 7: Report to GDS","k":"Data cataloguing step","u":"cataloguing.html#cat-report","s":"Submit an assured return on time. Prepare the return from catalogue records, not by retyping them. Collate and assure ALB returns. Check the return before submi"},{"t":"Cataloguing step 8: Maintain and review","k":"Data cataloguing step","u":"cataloguing.html#cat-maintain","s":"Records stay true. Review every record at least every 12 months. Update records when the asset changes, and when the owner leaves. Retire assets that are no lon"},{"t":"Candidate and designation log","k":"Data cataloguing template","u":"cataloguing.html#T-CAT-1","s":"Candidate Found in (catalogue, IAR or sharing register) Provided to or acquired from Purpose (one or more of seven) Scope tests passed Designated (yes or no) Re"},{"t":"Critical data asset catalogue record","k":"Data cataloguing template","u":"cataloguing.html#T-CAT-2","s":"title alternativeTitle description identifier creator dateCreated temporalCoverage conformsTo accessRights securityClassification licence mediaType expires supe"},{"t":"Annual record review","k":"Data cataloguing template","u":"cataloguing.html#T-CAT-3","s":"Asset Date Still critical (and why) Owner and successor confirmed Metadata checked against the guidance Changes made Signed off by (role)"},{"t":"Entity and relationship list","k":"Data cataloguing template","u":"cataloguing.html#T-CAT-4","s":"Entity Description Key attributes Related entity Relationship (for example, places) Cardinality (one to one, one to many or many to many) Optional or mandatory "},{"t":"Quality step 1: Identify critical data","k":"Data quality step","u":"quality.html#dq-identify","s":"Know which data items in each asset matter most. Name the 5 to 15 data items that drive the most important decisions (critical data elements). Record who uses t"},{"t":"Quality step 2: Define rules and targets","k":"Data quality step","u":"quality.html#dq-define","s":"Turn 'good enough' into rules a computer can test. Choose the dimensions that matter - completeness, uniqueness, consistency, timeliness, validity, accuracy. Wr"},{"t":"Quality step 3: Measure a baseline","k":"Data quality step","u":"quality.html#dq-baseline","s":"Know where you are today. Profile the data and run every rule; record the date and data version. Log every failure as an issue with its size and who it affects."},{"t":"Quality step 4: Prioritise and set goals","k":"Data quality step","u":"quality.html#dq-prioritise","s":"Fix what hurts most first. Score each issue with the issues framework. Resolve Critical immediately, High within one cycle, Medium within three and Low within s"},{"t":"Quality step 5: Fix causes at source","k":"Data quality step","u":"quality.html#dq-improve","s":"Stop problems coming back. Ask why until you reach the cause - people, process, system, supplier or standard. Prefer prevention at entry over downstream cleanin"},{"t":"Quality step 6: Report openly","k":"Data quality step","u":"quality.html#dq-report","s":"Users know how good the data is and what it should not be used for. Update a plain-English data quality statement - scores, trends, known issues and unsuitable "},{"t":"Quality step 7: Repeat and sustain","k":"Data quality step","u":"quality.html#dq-sustain","s":"Quality stays good without heroics. Run checks automatically on each load or on a fixed cycle. Track trends and alert when a rule drops below target. Escalate w"},{"t":"Quality step 8: Review every year","k":"Data quality step","u":"quality.html#dq-review","s":"Rules and targets still match what users need. Review rules, targets and the plan with the owner and users. Add rules for new uses, including AI. Retire rules t"},{"t":"Data quality rule","k":"Data quality template","u":"quality.html#T-DQ-1","s":"Rule ID Data element Plain-English rule Dimension Test Importance (1-4) Impact (1-4) Combined score Target (%) Owner (role) Date agreed"},{"t":"Issue log entry","k":"Data quality template","u":"quality.html#T-DQ-2","s":"Issue ID Date found Rule ID Records affected Users or groups affected Performance and target Band Priority Target resolution date Root cause Action and owner (r"},{"t":"Data quality statement","k":"Data quality template","u":"quality.html#T-DQ-3","s":"Asset and version Date Summary in plain English Scores by dimension and trend Known issues Quality by group where lawful Fit for Not fit for How to report a pro"},{"t":"DAM-R01 (must)","k":"Policy requirement","u":"dam.html#DAM-R01","s":"Identify the data assets in scope: classified OFFICIAL (including handling markings such as 'personal'), meeting the critical data asset criteria, and inside yo"},{"t":"DAM-R02 (must)","k":"Policy requirement","u":"dam.html#DAM-R02","s":"Identify and manage metadata about in-scope assets within your data catalogues."},{"t":"DAM-R03 (must)","k":"Policy requirement","u":"dam.html#DAM-R03","s":"Report in-scope assets to GDS. Departments provide metadata on their assets and coordinate and assure the returns of their ALBs."},{"t":"DAM-R04 (must)","k":"Policy requirement","u":"dam.html#DAM-R04","s":"Maintain metadata and review it every year."},{"t":"DAM-R05 (must)","k":"Policy requirement","u":"dam.html#DAM-R05","s":"Every identified asset has a named data owner, accountable for decisions about the data."},{"t":"DAM-R06 (must)","k":"Policy requirement","u":"dam.html#DAM-R06","s":"Every identified asset has a data quality action plan (DQAP) or an equivalent mechanism for managing its quality."},{"t":"DAM-R07 (should)","k":"Policy requirement","u":"dam.html#DAM-R07","s":"Where you already manage the quality of critical data, review those processes to confirm they cover every step of the DQAP implementation guide."},{"t":"DAM-R08 (must)","k":"Policy requirement","u":"dam.html#DAM-R08","s":"The chief data officer of each in-scope organisation implements the policy; the Chief Data Officer Council oversees implementation; the minister writes to minis"},{"t":"DAM-R09 (must)","k":"Policy requirement","u":"dam.html#DAM-R09","s":"Choose an ownership option (keep the IAO model, adopt the data ownership model, or a hybrid) and still meet the mandatory IAO actions, with governance covering "},{"t":"DAM-R10 (must)","k":"Policy requirement","u":"dam.html#DAM-R10","s":"When a data owner leaves, tell the coordinating team, have a successor ready and give the successor's details so the metadata can be updated."},{"t":"DAM-R11 (should)","k":"Policy requirement","u":"dam.html#DAM-R11","s":"Each critical data asset supports at least one of the seven purposes: public service delivery; legislative, legal or contractual requirement; defence, national "},{"t":"DAM-R12 (should)","k":"Policy requirement","u":"dam.html#DAM-R12","s":"If you designate a particular distribution of a data set, designate its source data set as well."},{"t":"DAM-R13 (should)","k":"Policy requirement","u":"dam.html#DAM-R13","s":"Record the metadata properties set out in the metadata guidance, in plain English, with ISO 8601 dates and 'unknown' or 'not applicable' rather than blanks."},{"t":"DAM-R14 (should)","k":"Policy requirement","u":"dam.html#DAM-R14","s":"The chief data officer, or the most senior data official, leads identification and appoints a coordinating team or person, drawing in owners, IAOs, stewards, se"},{"t":"DAM-R15 (method)","k":"Policy requirement","u":"dam.html#DAM-R15","s":"Prioritise quality issues with the issues framework: importance of purpose times impact sets the target range; the band below target sets priority. Its resoluti"},{"t":"DAM-R16 (gap)","k":"Policy requirement","u":"dam.html#DAM-R16","s":"The policy's introduction promises minimum requirements for interoperability, but the policy body does not state them. Treat the metadata guidance and the MEM a"},{"t":"Data asset","k":"Glossary term","u":"knowledge.html#c-data-asset","s":"One or more data sets plus, where relevant, the data services used to access them. "},{"t":"Data set","k":"Glossary term","u":"knowledge.html#c-data-set","s":"A structured collection of data selected and organised for a defined outcome or need. It can be a subset of a larger system. dataset"},{"t":"Data service","k":"Glossary term","u":"knowledge.html#c-data-service","s":"A controlled means of accessing one or more data sets, such as an API or secure access mechanism. API access service"},{"t":"Distribution","k":"Glossary term","u":"knowledge.html#c-distribution","s":"A specific representation of a data set, for example a CSV file or a feed. representation"},{"t":"Critical data asset","k":"Glossary term","u":"knowledge.html#c-cda","s":"A data asset shared across government where losing access could stop an organisation from fulfilling important functions. 'Essential shared data asset' is the o"},{"t":"Provided data","k":"Glossary term","u":"knowledge.html#c-provided","s":"Data one organisation gives to another to support an essential process or purpose the receiver is responsible for. "},{"t":"Acquired data","k":"Glossary term","u":"knowledge.html#c-acquired","s":"Data one organisation obtains from another to support an essential process or purpose it is responsible for. "},{"t":"Purpose","k":"Glossary term","u":"knowledge.html#c-purpose","s":"One of the seven reasons a critical data asset matters, such as public service delivery or official statistics. Each asset supports at least one. the seven purp"},{"t":"Scope tests","k":"Glossary term","u":"knowledge.html#c-scope-tests","s":"The conditions an asset must meet to be in scope of the policy: classified OFFICIAL, critical, and within the provider's ownership accountabilities. "},{"t":"Metadata","k":"Glossary term","u":"knowledge.html#c-metadata","s":"Information that describes a data asset so it can be found, understood, validated, reused and shared. data about data"},{"t":"Data catalogue","k":"Glossary term","u":"knowledge.html#c-catalogue","s":"A managed collection of metadata records that helps people and systems find, understand and reuse data assets. It holds descriptions, not the data. catalog meta"},{"t":"DCAT","k":"Glossary term","u":"knowledge.html#c-dcat","s":"The W3C vocabulary for describing data sets and data services in catalogues, so catalogues can be harvested and searched together. Data Catalog Vocabulary"},{"t":"Metadata Exchange Model","k":"Glossary term","u":"knowledge.html#c-mem","s":"The UK cross-government model, based on DCAT, for the metadata exchanged about data assets. xGov MEM MEM"},{"t":"Discoverability Platform","k":"Glossary term","u":"knowledge.html#c-discoverability","s":"The GDS service being scoped to link to departments' own catalogues and make critical data asset metadata discoverable across government. discovery service"},{"t":"Return","k":"Glossary term","u":"knowledge.html#c-return","s":"An organisation's report of its in-scope assets and their metadata to GDS, assured by the department for its ALBs. CDA return baseline return annual return"},{"t":"Data owner","k":"Glossary term","u":"knowledge.html#c-data-owner","s":"A senior leader accountable for the meaning, content, quality and management of a data asset. "},{"t":"Information asset owner","k":"Glossary term","u":"knowledge.html#c-iao","s":"The role accountable to the SIRO for protecting the whole information asset. Related to, but not the same as, the data owner. IAO"},{"t":"Data steward","k":"Glossary term","u":"knowledge.html#c-data-steward","s":"The role running an asset day to day: standards, access, quality processes and documentation. "},{"t":"Data custodian","k":"Glossary term","u":"knowledge.html#c-data-custodian","s":"The technical expert for the system holding the data: storage, access controls, auditable change and disposal. "},{"t":"Data role","k":"Glossary term","u":"knowledge.html#c-role","s":"A defined set of accountabilities for data. Records name roles, not people. "},{"t":"Ownership option","k":"Glossary term","u":"knowledge.html#c-ownership-option","s":"The choice between keeping the IAO model, adopting the data ownership model, or a hybrid. Each must still meet the mandatory IAO actions. IAO model hybrid model"},{"t":"Recipe","k":"Glossary term","u":"knowledge.html#c-recipe","s":"One of the five repeatable governance activities: Mandate, Frame, Assign, Operate, Assure. governance recipe"},{"t":"Governance charter","k":"Glossary term","u":"knowledge.html#c-charter","s":"A one-page statement of a governance body's purpose, scope, authority and review cadence. charter"},{"t":"Decision log","k":"Glossary term","u":"knowledge.html#c-decision-log","s":"A running record of governance decisions: what, who, why, when and the review trigger. "},{"t":"Exception","k":"Glossary term","u":"knowledge.html#c-exception","s":"A logged, time-bound deviation from policy with an owner and an expiry date. An exception without an expiry is an undocumented policy change. policy exception"},{"t":"RACI","k":"Glossary term","u":"knowledge.html#c-raci","s":"Responsible, Accountable, Consulted, Informed. One accountable role per activity. decision rights"},{"t":"Data quality action plan","k":"Glossary term","u":"knowledge.html#c-dqap","s":"The plan every identified asset must have, or an equivalent mechanism, for managing its quality across seven steps. DQAP"},{"t":"Critical data element","k":"Glossary term","u":"knowledge.html#c-cde","s":"A data item whose quality drives the most important decisions made with the asset. CDE"},{"t":"Data quality dimension","k":"Glossary term","u":"knowledge.html#c-dimension","s":"A measurable aspect of quality. The framework's six are completeness, uniqueness, consistency, timeliness, validity and accuracy. dimension"},{"t":"Issues framework","k":"Glossary term","u":"knowledge.html#c-issues-framework","s":"The GDS method that scores importance times impact to set targets, and uses the band below target to set priority and time to resolve. data quality issues frame"},{"t":"Data quality statement","k":"Glossary term","u":"knowledge.html#c-dq-statement","s":"A plain-English summary of an asset's quality, known issues and what it should not be used for. quality statement"},{"t":"Data Quality Vocabulary","k":"Glossary term","u":"knowledge.html#c-dqv","s":"The W3C vocabulary for publishing quality measurements with a catalogue record. DQV"},{"t":"Data contract","k":"Glossary term","u":"knowledge.html#c-data-contract","s":"Quality rules and promises written down as a file that suppliers and users share. ODCS"},{"t":"Data maturity","k":"Glossary term","u":"knowledge.html#c-maturity","s":"An organisation's capability around data, self-assessed with the government framework. DMA"},{"t":"Lead policy coordinator","k":"Glossary term","u":"knowledge.html#c-coordinator","s":"The person each organisation nominates to coordinate DAM Policy adoption and the return, and to sit on the Working Group. policy coordinator"},{"t":"MoSCoW","k":"Glossary term","u":"knowledge.html#c-moscow","s":"A way of ranking requirements or aims: Must have, Should have, Could have and Won't have this time. Must Should Could Won't priority"},{"t":"Request for information","k":"Glossary term","u":"knowledge.html#c-rfi","s":"Questions sent to suppliers before a tender to learn what the market offers and how products meet your requirements. RFI"},{"t":"Tender","k":"Glossary term","u":"knowledge.html#c-tender","s":"The formal invitation to suppliers to bid, with the requirements schedule, how bids will be evaluated and the contract terms. invitation to tender ITT request f"},{"t":"Functional requirement","k":"Glossary term","u":"knowledge.html#c-functional-req","s":"What a tool must do, such as export catalogue records as DCAT. FR"},{"t":"Non-functional requirement","k":"Glossary term","u":"knowledge.html#c-nonfunctional-req","s":"How well a tool must do it, such as accessibility, security, availability or the ability to export everything and leave. NFR"},{"t":"Proof of concept","k":"Glossary term","u":"knowledge.html#c-poc","s":"A short test of a product with your own data, to see whether it does what the supplier says before you buy. PoC"},{"t":"Exit plan","k":"Glossary term","u":"knowledge.html#c-exit-plan","s":"How you would move your data and content out of a product, with the formats, steps, time and cost, written before you sign and tested each year. exit strategy"},{"t":"Continuing professional development","k":"Glossary term","u":"knowledge.html#c-cpd","s":"The learning you record to keep your skills current, often required by a professional body to keep a certification or chartered status. CPD"},{"t":"Data literacy","k":"Glossary term","u":"knowledge.html#c-data-literacy","s":"How well people across an organisation can read, understand, question and use data, and talk about it with confidence. data skills"},{"t":"Cross-reference","k":"Glossary term","u":"knowledge.html#c-cross-reference","s":"A link from one piece of guidance to another. Inbound means other guidance points to the DAM Policy. Outbound means the DAM guidance points to other guidance. i"},{"t":"Chief data officer","k":"Role","u":"together.html#role-CDO","s":"Implements the policy in the organisation and leads the identification exercise; sponsors governance."},{"t":"Lead policy coordinator","k":"Role","u":"together.html#role-COO","s":"Coordinates identification, collates and assures the return (including ALBs), and is the link to the Working Group."},{"t":"Data governance board","k":"Role","u":"together.html#role-BRD","s":"Sets policy direction, resolves escalations and sees every asset's status. Chaired by the CDO, SIRO or equivalent."},{"t":"Data owner","k":"Role","u":"together.html#role-OWN","s":"Senior leader accountable for the meaning, content, quality and management of the asset; approves changes and signs off targets and risks."},{"t":"Information asset owner","k":"Role","u":"together.html#role-IAO","s":"Accountable to the SIRO for protecting the whole information asset; may hold data owner duties under the IAO or hybrid option."},{"t":"Data steward","k":"Role","u":"together.html#role-STW","s":"Runs the asset day to day: policies and standards, access, quality processes and documentation such as the business glossary in the catalogue."},{"t":"Data custodian","k":"Role","u":"together.html#role-CUS","s":"Technical expert for the system holding the data: storage, access controls, auditable change and disposal."},{"t":"Catalogue manager","k":"Role","u":"together.html#role-CAT","s":"Runs the organisation's catalogue, its metadata standard and its harvest feed."},{"t":"Data quality lead or analyst","k":"Role","u":"together.html#role-DQL","s":"Methods, profiling, tooling and reporting for data quality."},{"t":"Data protection officer","k":"Role","u":"together.html#role-DPO","s":"Independent advice on lawful basis, DPIAs and data subject rights."},{"t":"Data users","k":"Role","u":"together.html#role-USR","s":"Teams, services and other organisations that rely on the data; say what they need and report problems."},{"t":"People the data describes","k":"Role","u":"together.html#role-PUB","s":"Citizens, communities and their representatives; help spot exclusion and test whether quality information is understandable."},{"t":"Senior responsible owner","k":"Role","u":"together.html#role-SRO","s":"Accountable for a programme or project meeting its objectives. Makes sure data assets the change creates, alters or retires have owners, budgets and assurance, "},{"t":"Programme or project manager","k":"Role","u":"together.html#role-PDM","s":"Plans and runs the change. Builds DAM activities into the plan, the risk register and gate criteria, and makes sure data owners are consulted at each stage."},{"t":"Service or product owner","k":"Role","u":"together.html#role-SVO","s":"Owns the service the change delivers. Decides what data the service collects and exposes, and shows DAM evidence at service assessments."},{"t":"Design authority or solution architect","k":"Role","u":"together.html#role-ARC","s":"Approves data models, platforms and integrations. Checks new designs use open standards, documented schemas and an exit route, so they do not become future lega"},{"t":"Data migration lead","k":"Role","u":"together.html#role-MIG","s":"Plans and runs data migration. Profiles quality before moving data, reconciles after, and keeps catalogue entries and ownership in step."},{"t":"Commercial lead","k":"Role","u":"together.html#role-CML","s":"Runs procurement and manages contracts. Writes data ownership, metadata delivery, quality reporting and exit into contracts."},{"t":"Programme office and assurance","k":"Role","u":"together.html#role-PMO","s":"Tracks delivery and organises assurance reviews. Checks DAM checkpoints are met at each gate and reports gaps to the senior responsible owner."},{"t":"Data asset management policy in government","k":"Library: Policy","u":"library.html#LIB-01","s":""},{"t":"Identifying and recording critical data assets","k":"Library: Guidance","u":"library.html#LIB-02","s":""},{"t":"Recording metadata to describe critical data assets","k":"Library: Guidance","u":"library.html#LIB-03","s":""},{"t":"Data ownership model","k":"Library: Guidance","u":"library.html#LIB-04","s":""},{"t":"The role of information asset owners in government","k":"Library: Guidance","u":"library.html#LIB-05","s":""},{"t":"The Government Data Quality Framework","k":"Library: Framework","u":"library.html#LIB-06","s":""},{"t":"Data quality action plan implementation guide and template","k":"Library: Guidance","u":"library.html#LIB-07","s":""},{"t":"Data quality issues framework","k":"Library: Method","u":"library.html#LIB-08","s":""},{"t":"Data maturity assessment for government","k":"Library: Framework","u":"library.html#LIB-09","s":""},{"t":"UK Cross-Government Metadata Exchange Model","k":"Library: Standard","u":"library.html#LIB-10","s":""},{"t":"DCAT version 3","k":"Library: Standard","u":"library.html#LIB-11","s":""},{"t":"W3C Data Quality Vocabulary","k":"Library: Standard","u":"library.html#LIB-12","s":""},{"t":"Open Data Contract Standard","k":"Library: Standard","u":"library.html#LIB-13","s":""},{"t":"Public Sector Data Quality Commons (tools and playbook)","k":"Library: Toolkit","u":"library.html#LIB-14","s":""},{"t":"Data manual, data management section","k":"Library: Index","u":"library.html#LIB-15","s":""},{"t":"Data Cataloguing Playbook v2.6 and learner journey","k":"Library: Playbook","u":"library.html#LIB-16","s":"Held internally; not public. Its content is what the cataloguing stages here should be checked against (OR-01)."},{"t":"Data Governance Playbook suite (main manual, toolkit, templates, pocket guides, assessment, Command Centre)","k":"Library: Playbook","u":"library.html#LIB-17","s":"The source of the five recipes. Decks in the suite stay outside this repository."},{"t":"Canonical shared glossary of the data playbook compendium","k":"Library: Vocabulary","u":"library.html#LIB-18","s":"The terms here reconcile with it; eight conflicts it logged are tracked in the open register."},{"t":"Data Maturity and Transformation suite (MAT-01 to MAT-05) and crosswalk spine","k":"Library: Playbook","u":"library.html#LIB-19","s":"Spine indicators S04, S08, S09 and S10 map to the three capabilities."},{"t":"DQAP template workbook","k":"Library: Template","u":"library.html#LIB-20","s":"Downloadable from the DQAP guide; the Commons can produce a filled one from rule results."},{"t":"Chief data officer","k":"Your role: route and learning journey","u":"personas.html#persona-cdo","s":"You are accountable for adopting the policy across your organisation and, in a department, its arm's length bodies."},{"t":"Lead policy coordinator","k":"Your role: route and learning journey","u":"personas.html#persona-coo","s":"You coordinate adoption day to day, collate and assure the return, and represent your organisation at the Working Group."},{"t":"Data owner","k":"Your role: route and learning journey","u":"personas.html#persona-own","s":"You are the senior leader accountable for the meaning, content, quality and management of one or more critical data assets."},{"t":"Data steward","k":"Your role: route and learning journey","u":"personas.html#persona-stw","s":"You run critical data assets day to day - their standards, access, metadata and quality processes."},{"t":"Catalogue manager or data custodian","k":"Your role: route and learning journey","u":"personas.html#persona-cat","s":"You run the catalogue and the systems behind it, so records can be found, harvested and kept accurate."},{"t":"Data quality lead or analyst","k":"Your role: route and learning journey","u":"personas.html#persona-dql","s":"You bring methods and tools for measuring and improving quality across many assets."},{"t":"Programme or project lead","k":"Your role: route and learning journey","u":"personas.html#persona-prg","s":"You lead a medium or large change programme or project that creates, changes, migrates or retires critical data assets."},{"t":"Commercial or technology lead","k":"Your role: route and learning journey","u":"personas.html#persona-buy","s":"You choose, buy or build the tools that catalogue, check and govern critical data, and you write the contracts that keep the data yours."},{"t":"M01 The DAM Policy - what it asks of you","k":"Learning module (Foundation)","u":"learning.html#M01","s":"Explain who the policy applies to and what is in scope Name the core duties: identify and catalogue assets, report them, name an owner and manage quality Find t"},{"t":"M02 Roles and accountability","k":"Learning module (Foundation)","u":"learning.html#M02","s":"Describe the data owner, data steward and data custodian roles Explain how the data owner relates to the information asset owner Choose between the three owners"},{"t":"M03 Setting up governance with five recipes","k":"Learning module (Practitioner)","u":"learning.html#M03","s":"Run the Mandate, Frame, Assign, Operate and Assure recipes in order Set up a decision log and an exception register Collect evidence continuously for the GDS re"},{"t":"M04 Finding and designating critical data assets","k":"Learning module (Practitioner)","u":"learning.html#M04","s":"Build a candidate list from existing registers Apply the scope tests and the seven purposes Draw an asset's boundary and record why"},{"t":"M05 Describing assets with metadata others can use","k":"Learning module (Practitioner)","u":"learning.html#M05","s":"Record the metadata properties in the GOV.UK guidance Write titles and descriptions in plain English Map properties to the Metadata Exchange Model"},{"t":"M06 Cataloguing, harvesting and reporting to GDS","k":"Learning module (Practitioner)","u":"learning.html#M06","s":"Expose records so others can harvest them Produce the return from catalogue records Plan the annual review"},{"t":"M07 Data quality foundations","k":"Learning module (Foundation)","u":"learning.html#M07","s":"Name the five principles and six dimensions of the Government Data Quality Framework Explain what a DQAP is for Recognise when quality differs between groups of"},{"t":"M08 Building a DQAP and scoring issues","k":"Learning module (Practitioner)","u":"learning.html#M08","s":"Write rules with targets from the issues framework Measure a baseline and log issues Prioritise issues and set resolution dates"},{"t":"M09 Running the three capabilities as one yearly cycle","k":"Learning module (Advanced)","u":"learning.html#M09","s":"Use the hand-offs so each fact is recorded once Plan one annual review per asset Feed assurance lessons into the next mandate"},{"t":"M10 Inclusive data practice","k":"Learning module (Foundation)","u":"learning.html#M10","s":"Apply equality and inclusion checks in each capability Make data quality statements and records accessible Involve people the data describes"},{"t":"M11 Embedding the policy in delivery and change","k":"Learning module (Practitioner)","u":"learning.html#M11","s":"Name the capabilities the policy relies on but does not state Build DAM checkpoints into a business case and an assurance plan Plan a legacy exit and a handover"},{"t":"M12 What makes a critical data asset AI-ready","k":"Learning module (Foundation)","u":"learning.html#M12","s":"Name the four pillars in the GDS guidelines on AI-ready datasets Decide whether an asset needs the AI-ready supplement Explain why AI-readiness is a stewardship"},{"t":"M13 From FAIR to AI-ready metadata","k":"Learning module (Practitioner)","u":"learning.html#M13","s":"Explain the four FAIR principles in plain English Add the AI-ready catalogue fields to a record See how the proposed DCAT-AP-UK profile extends the xGov MEM for"},{"t":"M14 Start from the question the data must answer","k":"Learning module (Practitioner)","u":"learning.html#M14","s":"Write down the decision or question an AI use of an asset serves Test that question against the seven purposes in the policy Record out-of-scope uses before any"},{"t":"M15 Connecting data to AI with linked data, knowledge graphs and MCP","k":"Learning module (Advanced)","u":"learning.html#M15","s":"Explain the RDF triple and why linked data helps machines read metadata Find and reuse this portal's knowledge graph and vocabulary files Describe how an MCP se"},{"t":"M16 Making public data AI-ready together","k":"Learning module (Practitioner)","u":"learning.html#M16","s":"Look for existing work before building, across public sector code and catalogues Involve the people the data describes when you judge whether it is fit for AI U"},{"t":"M17 Governing AI use of critical data in practice","k":"Learning module (Advanced)","u":"learning.html#M17","s":"Run the AI-ready quality rules on a sample file Apply the transparency and ethics duties that go with AI use Plan who monitors drift and bias once AI use begins"},{"t":"M18 Leading data asset management - your first year","k":"Learning module (Foundation)","u":"learning.html#M18","s":"Set Must, Should and Could aims for your organisation and the outcomes each brings Plan the first 30, 60 and 90 days and the 6 and 12 month checkpoints Choose t"},{"t":"M19 Buying tools for data asset management without lock-in","k":"Learning module (Practitioner)","u":"learning.html#M19","s":"Pick the requirements that fit the kinds of tool you need, with priorities Run a request for information and a proof of concept with your own data Ask for contr"},{"t":"Health and care data","k":"Sector supplement","u":"sectors.html#SUP-HLT","s":"For critical data assets that hold patient-level or care records. Adds the health roles, duties and coding standards the core playbooks do not cover."},{"t":"HLT-01 NHS number is recorded","k":"Health and care data quality rule","u":"sectors.html#HLT-01","s":"NHS number"},{"t":"HLT-02 NHS number is 10 digits with a valid modulus 11 check digit","k":"Health and care data quality rule","u":"sectors.html#HLT-02","s":"NHS number"},{"t":"HLT-03 Date of birth is not in the future","k":"Health and care data quality rule","u":"sectors.html#HLT-03","s":"Date of birth"},{"t":"HLT-04 Provider organisation code is in ODS format","k":"Health and care data quality rule","u":"sectors.html#HLT-04","s":"Organisation code"},{"t":"HLT-05 Primary diagnosis is in ICD-10 code format","k":"Health and care data quality rule","u":"sectors.html#HLT-05","s":"Diagnosis"},{"t":"HLT-06 Ethnic category is not unknown or not stated","k":"Health and care data quality rule","u":"sectors.html#HLT-06","s":"Ethnicity"},{"t":"HLT-07 NHS number completeness does not differ by more than 5 points between ethnic groups","k":"Health and care data quality rule","u":"sectors.html#HLT-07","s":"NHS number by group"},{"t":"Adult and children's social care data","k":"Sector supplement","u":"sectors.html#SUP-SOC","s":"For assets built from council returns, such as adult social care client level data and children's social care census returns, where the source systems sit outsi"},{"t":"SOC-01 Supplying council is a valid GSS code","k":"Adult and children's social care data quality rule","u":"sectors.html#SOC-01","s":"Council code"},{"t":"SOC-02 NHS number is valid where present, so care and health records can be linked","k":"Adult and children's social care data quality rule","u":"sectors.html#SOC-02","s":"NHS number"},{"t":"SOC-03 Event dates are not in the future","k":"Adult and children's social care data quality rule","u":"sectors.html#SOC-03","s":"Event date"},{"t":"SOC-04 Each council's latest submission is no more than one quarter and 30 days old","k":"Adult and children's social care data quality rule","u":"sectors.html#SOC-04","s":"Submission"},{"t":"SOC-05 Each event is recorded once for each person","k":"Adult and children's social care data quality rule","u":"sectors.html#SOC-05","s":"Person and event"},{"t":"Geospatial and address data","k":"Sector supplement","u":"sectors.html#SUP-GEO","s":"For assets that hold addresses, coordinates or map geometry. Adds geospatial metadata, open identifiers and positional quality."},{"t":"GEO-01 UPRN is recorded","k":"Geospatial and address data quality rule","u":"sectors.html#GEO-01","s":"UPRN"},{"t":"GEO-02 UPRN is 1 to 12 digits","k":"Geospatial and address data quality rule","u":"sectors.html#GEO-02","s":"UPRN"},{"t":"GEO-03 Postcode is in Royal Mail format","k":"Geospatial and address data quality rule","u":"sectors.html#GEO-03","s":"Postcode"},{"t":"GEO-04 Easting is within the British National Grid range","k":"Geospatial and address data quality rule","u":"sectors.html#GEO-04","s":"Easting"},{"t":"GEO-05 Northing is within the British National Grid range","k":"Geospatial and address data quality rule","u":"sectors.html#GEO-05","s":"Northing"},{"t":"GEO-06 Area code is a GSS code","k":"Geospatial and address data quality rule","u":"sectors.html#GEO-06","s":"Area code"},{"t":"Official statistics and administrative sources","k":"Sector supplement","u":"sectors.html#SUP-STA","s":"For assets used to produce official statistics. Joins the DQAP to quality assurance of administrative data, so quality is reported once for both purposes."},{"t":"STA-01 Reference period is complete with no missing months","k":"Official statistics and administrative sources quality rule","u":"sectors.html#STA-01","s":"Reference period"},{"t":"STA-02 Monthly totals are not implausible outliers","k":"Official statistics and administrative sources quality rule","u":"sectors.html#STA-02","s":"Counts"},{"t":"STA-03 Area codes are valid GSS codes","k":"Official statistics and administrative sources quality rule","u":"sectors.html#STA-03","s":"Geography"},{"t":"STA-04 Every measure column names its unit","k":"Official statistics and administrative sources quality rule","u":"sectors.html#STA-04","s":"Units"},{"t":"Data sharing and legal gateways","k":"Sector supplement","u":"sectors.html#SUP-SHR","s":"For every critical data asset that includes personal data, because critical data assets are defined by being shared. Adds a legal gateway record to the governan"},{"t":"SHR-01 Every shared extract carries the agreement reference","k":"Data sharing and legal gateways quality rule","u":"sectors.html#SHR-01","s":"Agreement reference"},{"t":"SHR-02 Extracts arrive on the agreed schedule","k":"Data sharing and legal gateways quality rule","u":"sectors.html#SHR-02","s":"Extract date"},{"t":"SHR-03 Only the columns in the agreement are present","k":"Data sharing and legal gateways quality rule","u":"sectors.html#SHR-03","s":"Columns"},{"t":"AI-ready data","k":"Sector supplement","u":"sectors.html#SUP-AI","s":"For assets used, or likely to be used, for AI or automated decision support. Turns the GOV.UK AI-ready data guidance into checks at the annual review."},{"t":"AI-01 Training labels are complete","k":"AI-ready data quality rule","u":"sectors.html#AI-01","s":"Label"},{"t":"AI-02 Label completeness does not differ by more than 5 points between groups","k":"AI-ready data quality rule","u":"sectors.html#AI-02","s":"Label by group"},{"t":"AI-03 Each record appears once, so training and test sets do not overlap","k":"AI-ready data quality rule","u":"sectors.html#AI-03","s":"Record"},{"t":"AI-04 Numeric features have no implausible outliers","k":"AI-ready data quality rule","u":"sectors.html#AI-04","s":"Features"},{"t":"Fraud and error","k":"Sector supplement","u":"sectors.html#SUP-FRD","s":"For assets used to detect fraud or error, where identity matching quality decides who is flagged."},{"t":"FRD-01 National Insurance number is in a valid format","k":"Fraud and error quality rule","u":"sectors.html#FRD-01","s":"National Insurance number"},{"t":"FRD-02 Each person appears once in the matching base","k":"Fraud and error quality rule","u":"sectors.html#FRD-02","s":"Person"},{"t":"FRD-03 Date of birth is recorded, so matches are not made on name alone","k":"Fraud and error quality rule","u":"sectors.html#FRD-03","s":"Date of birth"},{"t":"Justice, policing and national security","k":"Sector supplement","u":"sectors.html#SUP-JUS","s":"For assets in law enforcement, justice, defence or security settings, where only OFFICIAL assets are in scope and metadata itself may be sensitive."},{"t":"JUS-01 Every record carries a classification marking from the allowed list","k":"Justice, policing and national security quality rule","u":"sectors.html#JUS-01","s":"Classification"},{"t":"JUS-02 Event dates are not in the future","k":"Justice, policing and national security quality rule","u":"sectors.html#JUS-02","s":"Event date"},{"t":"Data about people","k":"Sector supplement","u":"sectors.html#SUP-PER","s":"For any asset that holds records about individual people. Makes sure forms and rules let people describe themselves accurately."},{"t":"PER-01 Family name is recorded","k":"Data about people quality rule","u":"sectors.html#PER-01","s":"Name"},{"t":"PER-02 Date of birth is not in the future","k":"Data about people quality rule","u":"sectors.html#PER-02","s":"Date of birth"},{"t":"PER-03 Each person is recorded once","k":"Data about people quality rule","u":"sectors.html#PER-03","s":"Person"},{"t":"PER-04 Ethnicity is not unknown, where it is lawfully collected","k":"Data about people quality rule","u":"sectors.html#PER-04","s":"Ethnicity"},{"t":"Reference data and identifiers","k":"Sector supplement","u":"sectors.html#SUP-REF","s":"For assets that depend on code lists and identifiers maintained by other organisations, such as area codes, organisation codes and company numbers."},{"t":"REF-01 Area code is a GSS code","k":"Reference data and identifiers quality rule","u":"sectors.html#REF-01","s":"Area code"},{"t":"REF-02 Company number is in Companies House format","k":"Reference data and identifiers quality rule","u":"sectors.html#REF-02","s":"Company number"},{"t":"REF-03 LEI is valid, including its check digits","k":"Reference data and identifiers quality rule","u":"sectors.html#REF-03","s":"Legal entity identifier"},{"t":"REF-04 Charity number is in a valid format","k":"Reference data and identifiers quality rule","u":"sectors.html#REF-04","s":"Charity number"},{"t":"Records, retention and disposal","k":"Sector supplement","u":"sectors.html#SUP-REC","s":"For every critical data asset that must be kept, archived or destroyed on a schedule. Joins data asset management to records management."},{"t":"REC-01 Records are not older than the retention period in your schedule (this example uses 7 years)","k":"Records, retention and disposal quality rule","u":"sectors.html#REC-01","s":"Record date"},{"t":"Data architecture and models","k":"Sector supplement","u":"sectors.html#SUP-ARC","s":"For critical data assets whose structure others build on. Describes the entities, how they relate and which system is the authoritative source, and links them t"},{"t":"ARC-01 Each entity's key is unique","k":"Data architecture and models quality rule","u":"sectors.html#ARC-01","s":"Entity key"},{"t":"Devolved governments and local government","k":"Sector supplement","u":"sectors.html#SUP-DEV","s":"For assets that flow to or from the devolved governments or councils, which are not bound by the policy but often depend on it."},{"t":"DEV-01 Nation is recorded from the allowed list","k":"Devolved governments and local government quality rule","u":"sectors.html#DEV-01","s":"Nation"},{"t":"DEV-02 Area code is a GSS code","k":"Devolved governments and local government quality rule","u":"sectors.html#DEV-02","s":"Area code"},{"t":"Environmental, sensor and time-series data","k":"Sector supplement","u":"sectors.html#SUP-ENV","s":"For monitoring and sensor data where readings arrive continuously and gaps, units and drift matter more than missing fields."},{"t":"ENV-01 No gaps in the expected reading interval","k":"Environmental, sensor and time-series data quality rule","u":"sectors.html#ENV-01","s":"Timestamp"},{"t":"ENV-02 Every measure column names its unit","k":"Environmental, sensor and time-series data quality rule","u":"sectors.html#ENV-02","s":"Units"},{"t":"ENV-03 Readings have no implausible outliers","k":"Environmental, sensor and time-series data quality rule","u":"sectors.html#ENV-03","s":"Reading"},{"t":"Pupil and learner data","k":"Sector supplement","u":"sectors.html#SUP-EDU","s":"For assets about pupils and learners, which are long-lived and linked across schools, colleges and nations."},{"t":"EDU-01 School unique reference number is 6 digits","k":"Pupil and learner data quality rule","u":"sectors.html#EDU-01","s":"School"},{"t":"EDU-02 Each pupil appears once per census","k":"Pupil and learner data quality rule","u":"sectors.html#EDU-02","s":"Pupil"},{"t":"Service Standard","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-SVC","s":"The 14 points any government service is assessed against; used for this portal's self-assessment."},{"t":"The Technology Code of Practice","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-TCOP","s":"Make things open, use open standards and make data reusable: the basis for catalogue and tool choices."},{"t":"The GDS Way","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-GDSWAY","s":"Engineering practice this portal follows, including using GitHub and publishing a vulnerability disclosure route."},{"t":"Open standards for government","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-OPEN","s":"The recommended open standards, including those for metadata, identifiers and data exchange."},{"t":"Identifying property and street information (UPRN and USRN)","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-UPRN","s":"The open standard for property and street identifiers; the basis for address quality rules."},{"t":"Government Digital and Data Profession Capability Framework","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-DDAT","s":"Role and skill definitions for data governance and data roles."},{"t":"National Data Library (data.gov.uk)","k":"Rulebook: Data and AI","u":"dam.html#RB-NDL","s":"The cross-government gateway to public data; the destination for harvested catalogue records."},{"t":"Data and AI Ethics Framework","k":"Rulebook: Data and AI","u":"dam.html#RB-ETH","s":"Ethical questions for new or higher-risk uses of data, including AI."},{"t":"Making government datasets ready for AI","k":"Rulebook: Data and AI","u":"dam.html#RB-AIREADY","s":"The criteria to assess at the annual review when data is used for AI."},{"t":"AI Playbook for the UK Government","k":"Rulebook: Data and AI","u":"dam.html#RB-AIPLAY","s":"Safe and effective use of AI in government."},{"t":"Algorithmic Transparency Recording Standard hub","k":"Rulebook: Data and AI","u":"dam.html#RB-ATRS","s":"Transparency records for algorithmic tools that support decisions about people."},{"t":"Data (Use and Access) Act 2025","k":"Rulebook: Legislation","u":"dam.html#RB-DUAA","s":"Amends UK GDPR and the Data Protection Act 2018; affects the lawful basis for sharing."},{"t":"Data Protection Act 2018","k":"Rulebook: Legislation","u":"dam.html#RB-DPA","s":"Data protection law, including Part 3 for law enforcement processing."},{"t":"Digital Economy Act 2017","k":"Rulebook: Legislation","u":"dam.html#RB-DEA","s":"Data sharing powers for public authorities, including for fraud and debt."},{"t":"Equality Act 2010","k":"Rulebook: Legislation","u":"dam.html#RB-EQA","s":"Includes the public sector equality duty."},{"t":"ICO data sharing code of practice","k":"Rulebook: Legislation","u":"dam.html#RB-ICOSHARE","s":"Statutory code on sharing personal data between controllers (in force since October 2021, according to search results)."},{"t":"Government Security Classifications","k":"Rulebook: Security","u":"dam.html#RB-GSC","s":"Defines OFFICIAL and handling markings; the policy covers OFFICIAL assets only."},{"t":"Report a vulnerability on a GOV.UK domain or subdomain","k":"Rulebook: Security","u":"dam.html#RB-VDP","s":"The government vulnerability disclosure approach this portal's security.txt follows in spirit."},{"t":"Understanding accessibility requirements for public sector bodies","k":"Rulebook: Accessibility and equality","u":"dam.html#RB-ACC","s":"The accessibility regulations that apply to published records, statements and this portal."},{"t":"Model accessibility statement","k":"Rulebook: Accessibility and equality","u":"dam.html#RB-MODEL","s":"Mandatory wording used in this portal's accessibility statement."},{"t":"Public sector equality duty","k":"Rulebook: Accessibility and equality","u":"dam.html#RB-PSED","s":"How public bodies have due regard to equality in their functions, including data work."},{"t":"Writing to GOV.UK standards - style guides","k":"Rulebook: Content","u":"dam.html#RB-STYLE","s":"The style this portal is written in (the old GOV.UK style guide address redirects here)."},{"t":"Code of Practice for Statistics","k":"Rulebook: Statistics","u":"dam.html#RB-COP","s":"Trustworthiness, quality and value for official statistics; read across to DQAPs for statistical sources."},{"t":"Quality assurance of administrative data","k":"Rulebook: Statistics","u":"dam.html#RB-QAAD","s":"How statistics producers assure administrative data; the site blocked automated checking."},{"t":"Information management guidance","k":"Rulebook: Records","u":"dam.html#RB-TNA","s":"Records management, retention and disposal for public records."},{"t":"Open Government Licence v3.0","k":"Rulebook: Content","u":"dam.html#RB-OGL","s":"The licence for open government data and for this portal's content."},{"t":"Data Security and Protection Toolkit","k":"Rulebook: Health and care","u":"dam.html#RB-DSPT","s":"Annual self-assessment against data security standards for organisations with access to NHS patient data."},{"t":"The Caldicott Principles","k":"Rulebook: Health and care","u":"dam.html#RB-CALD","s":"Principles for using confidential information about patients and service users."},{"t":"Adult social care client level data, England: background quality and methodology","k":"Rulebook: Health and care","u":"dam.html#RB-CLD","s":"Quality and coverage of the national adult social care client level data collection."},{"t":"Adult social care outcomes framework: handbook of definitions","k":"Rulebook: Health and care","u":"dam.html#RB-ASCOF","s":"Definitions of measures derived from client level data."},{"t":"Care data matters: a roadmap for better adult social care data","k":"Rulebook: Health and care","u":"dam.html#RB-CDM","s":"The roadmap for adult social care data, including client level data."},{"t":"Children in need census: guide to submitting data","k":"Rulebook: Children and education","u":"dam.html#RB-CIN","s":"Specification and validation for children in need data returns."},{"t":"Best practice guidance and tools for managing geospatial data","k":"Rulebook: Geospatial","u":"dam.html#RB-GEOBP","s":"Guidance on managing and sharing geospatial data in a FAIR way."},{"t":"How FAIR are the UK's national geospatial data assets?","k":"Rulebook: Geospatial","u":"dam.html#RB-QFAIR","s":"The Q-FAIR assessment of national geospatial data assets."},{"t":"UK GEMINI metadata standard","k":"Rulebook: Geospatial","u":"dam.html#RB-GEMINI","s":"Geospatial metadata standard named in the GOV.UK metadata guidance; the AGI page says it has moved to GitHub."},{"t":"Public Sector Fraud Authority","k":"Rulebook: Fraud and error","u":"dam.html#RB-PSFA","s":"Counter-fraud standards and support for the fraud and error purpose."},{"t":"Local Digital Declaration","k":"Rulebook: Local government","u":"dam.html#RB-LDD","s":"Shared commitments for councils, which can adopt the policy voluntarily."},{"t":"SDMX","k":"Rulebook: Standards","u":"dam.html#RB-SDMX","s":"Statistical data and metadata exchange standard."},{"t":"Data Catalog Vocabulary (DCAT) version 3","k":"Rulebook: Standards","u":"dam.html#RB-DCAT","s":"The base vocabulary for catalogue records."},{"t":"Data on the Web Best Practices: Data Quality Vocabulary","k":"Rulebook: Standards","u":"dam.html#RB-DQV","s":"Publishing quality measurements with catalogue records."},{"t":"Gate Review 0: Strategic Assessment","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-GATE0","s":"NISTA's workbook for the strategic assessment of a programme."},{"t":"Gate Review 5: Operations Review and Benefits Realisation","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-GATE5","s":"NISTA's workbook for confirming benefits are being realised and the service is running smoothly."},{"t":"CDMP: Certified Data Management Professional","k":"Rulebook: Skills and professions","u":"dam.html#RB-CDMP","s":"DAMA International's certification for data management professionals, based on the DAMA-DMBOK."},{"t":"BCS Practitioner Certificate in Data Management Essentials","k":"Rulebook: Skills and professions","u":"dam.html#RB-BCSDME","s":"A practitioner certificate in good practice for managing an organisation's data."},{"t":"CILIP professional registration","k":"Rulebook: Skills and professions","u":"dam.html#RB-CILIPREG","s":"Certification, chartership and knowledge management chartership for information professionals, with yearly revalidation through CPD."},{"t":"The Green Book and accompanying guidance","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-GREEN","s":"Appraisal and the five case business case model; where the cost of owning, cataloguing and improving data assets belongs in a programme business case."},{"t":"Government Functional Standard GovS 002: Project Delivery","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-GOVS002","s":"The life cycle, governance and roles every portfolio, programme and project must follow; data deliverables and data owners fit into it."},{"t":"Government Functional Standard GovS 005: Digital","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-GOVS005","s":"The digital and data functional standard that the Data Maturity Assessment and data management practice sit under."},{"t":"Implementing integrated assurance for major projects","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-IAAP","s":"How major projects plan assurance; DAM checks can be written into the integrated assurance and approval plan."},{"t":"National Infrastructure and Service Transformation Authority","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-NISTA","s":"The centre of expertise for major projects and service transformation, including the Government Major Projects Portfolio."},{"t":"Government Major Projects Portfolio","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-GMPP","s":"The largest and riskiest projects; many create or replace critical data assets."},{"t":"Set up a commercial or digital and technology spend controls pipeline","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-SPEND","s":"Spend control is the point at which central teams see new digital and technology spend, and so a natural checkpoint for DAM evidence."},{"t":"HL7 FHIR UK Core","k":"Rulebook: Health and care","u":"dam.html#RB-FHIRUK","s":"API standards that use FHIR Release 4 to exchange health and care data consistently across England, Scotland, Wales and Northern Ireland. UK Core uses SNOMED CT"},{"t":"SNOMED CT","k":"Rulebook: Health and care","u":"dam.html#RB-SNOMED","s":"The information standard for clinical terminology (SCCI0034). Record it in conformsTo when an asset holds coded clinical data."},{"t":"DCB0129: Clinical risk management in the manufacture of health IT systems","k":"Rulebook: Health and care","u":"dam.html#RB-DCB0129","s":"Clinical risk management that suppliers of health IT must follow, including a clinical safety officer. Under national review with DCB0160."},{"t":"DCB0160: Clinical risk management in the deployment and use of health IT systems","k":"Rulebook: Health and care","u":"dam.html#RB-DCB0160","s":"Clinical risk management that health and care organisations must follow when they deploy and use health IT. A national review consulted until 11 September 2026."},{"t":"Advice on retention","k":"Rulebook: Records and information management","u":"dam.html#RB-TNARET","s":"Sets out short (up to two years), medium (up to eight years) and long retention categories, and says the model retention schedules are no longer maintained. Eac"},{"t":"Using metadata to describe data assets in a data catalogue","k":"Rulebook: Standards","u":"dam.html#RB-DCATGOV","s":"Recommends DCAT version 3 for describing data sets and data services in a catalogue, in support of the UK Cross-Government Metadata Exchange Model."},{"t":"Register of information sharing agreements under the Digital Economy Act 2017","k":"Rulebook: Legislation","u":"dam.html#RB-DEAREG","s":"The public register of agreements made under the public service delivery, debt, fraud and civil registration powers in Part 5 of the Act. Each agreement records"},{"t":"Data sharing: a code of practice - data sharing agreements","k":"Rulebook: Data protection","u":"dam.html#RB-ICODSA","s":"Says a data sharing agreement is good practice and lists what it should cover, including the parties, purpose, lawful basis, data items, formats, rights, retent"},{"t":"Confidential patient information and section 251","k":"Rulebook: Health and care","u":"dam.html#RB-S251","s":"Section 251 of the NHS Act 2006 and the Health Service (Control of Patient Information) Regulations 2002 let the common law duty of confidentiality be set aside"},{"t":"The Medical Devices Regulations 2002","k":"Rulebook: Health and care","u":"dam.html#RB-UKMDR","s":"Govern medical devices in Great Britain, including software and AI used for a medical purpose. The MHRA is reforming them."},{"t":"Medical devices: software applications (apps)","k":"Rulebook: Health and care","u":"dam.html#RB-MHRASW","s":"Helps decide whether software, including an app or AI, is a medical device. A product is a medical device only if its manufacturer intends a medical purpose."},{"t":"Data saves lives: reshaping health and social care with data","k":"Rulebook: Health and care","u":"dam.html#RB-DSL","s":"DHSC's data strategy for health and social care in England, which commits to secure data environments as the default way to access NHS data for research and ana"},{"t":"Secure data environment for NHS health and social care data - policy guidelines","k":"Rulebook: Health and care","u":"dam.html#RB-SDE","s":"Twelve guidelines that organisations hosting NHS health and social care data for research and analysis must adopt."},{"t":"Data access policy update","k":"Rulebook: Health and care","u":"dam.html#RB-DAPU","s":"Builds on the secure data environment guidelines with the policy decisions made so far on 'data access as default' for secondary uses of NHS data."},{"t":"Service assessments and applying the Service Standard","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-SVCASSESS","s":"Alpha, beta and live assessments; teams can show their critical data assets are catalogued, owned and quality-planned."},{"t":"Retiring your service","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-RETIRE","s":"What to do with users and their data when a service closes, including passing data to a new owner."},{"t":"Managing legacy technology","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-LEGACY","s":"Its second principle asks organisations to build a complete and accurate register of their data assets before migrating."},{"t":"Prevent technical debt and legacy","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-TECHDEBT","s":"Stops new systems becoming the next concentration of hard-to-use data."},{"t":"The Orange Book: management of risk","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-ORANGE","s":"Principles for managing risk; data asset risks belong on the same registers as other risks."},{"t":"The Magenta Book","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-MAGENTA","s":"Evaluation in government; how to show whether DAM work delivered its intended benefits."},{"t":"The AQuA Book","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-AQUA","s":"Quality assurance of analysis and models; analysis is only as reliable as the data quality plans behind it."},{"t":"The Sourcing Playbook","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-SOURCING","s":"Outsourcing decisions; contracts should say who owns the data, how metadata is delivered and how data comes back at exit."},{"t":"The Digital, Data and Technology Playbook","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-DDATPB","s":"Commercial guidance for buying digital, data and technology products and services."},{"t":"PPN 020: Guidance on data protection legislation","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-PPN020","s":"Data protection terms in public contracts."},{"t":"Data Sharing Governance Framework","k":"Rulebook: Data and AI","u":"dam.html#RB-DSGF","s":"Cross-government principles for sharing data; the DAM Policy does not force sharing but expects safe reuse."},{"t":"A blueprint for modern digital government","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-BLUEPRINT","s":"The wider programme of digital reform that the DAM Policy supports."},{"t":"National Data Library","k":"Rulebook: Data and AI","u":"dam.html#RB-NDLPUB","s":"Plans for making public sector data easier to find and use; catalogued critical assets are a natural input."},{"t":"Data Maturity Assessment for Government: Framework","k":"Rulebook: Data and AI","u":"dam.html#RB-DMAF","s":"10 topics, 6 themes and 5 levels for assessing data maturity. Licensed CC BY-NC-SA 4.0, so this portal links to it and does not copy its descriptions."},{"t":"Government data maturity hub","k":"Rulebook: Data and AI","u":"dam.html#RB-DMAHUB","s":"The framework plus guidance on delivering an assessment."},{"t":"Government professions","k":"Rulebook: Skills and professions","u":"dam.html#RB-PROFS","s":"The list of functional and specialist professions every civil servant can join."},{"t":"Government Skills","k":"Rulebook: Skills and professions","u":"dam.html#RB-GSKILLS","s":"Runs the Government Campus, the recommended curriculum and the Government Skills Campus learning platform."},{"t":"The Civil Service recommended curriculum","k":"Rulebook: Skills and professions","u":"dam.html#RB-CURRIC","s":"Recommended learning for all civil servants, searchable by subject."},{"t":"Data skills for all","k":"Rulebook: Skills and professions","u":"dam.html#RB-DSFA","s":"Free data learning at awareness, working and practitioner levels."},{"t":"Specialist skills from government professions","k":"Rulebook: Skills and professions","u":"dam.html#RB-SPECIALIST","s":"Strand 4 of the curriculum: how professions develop specialist skills."},{"t":"Government Campus prospectus","k":"Rulebook: Skills and professions","u":"dam.html#RB-PROSPECTUS","s":"The online prospectus of courses by strand and subject, including data and analytics."},{"t":"National School of Government","k":"Rulebook: Skills and professions","u":"dam.html#RB-NSG","s":"Opened in October 2026 to train civil servants and public sector leaders, including in AI."},{"t":"Analysis Function career framework","k":"Rulebook: Skills and professions","u":"dam.html#RB-AFCAREER","s":"Career framework and learning pathways for the analytical professions, including statistics."},{"t":"Analysis Function role profiles and career pathways","k":"Rulebook: Skills and professions","u":"dam.html#RB-AFROLES","s":"Role profiles for analysts, statisticians, economists, social researchers, operational researchers and geographers."},{"t":"Government Statistical Service and Statistician Group","k":"Rulebook: Skills and professions","u":"dam.html#RB-GSS","s":"The statistics profession, closest to data quality work on official statistics."},{"t":"Government Knowledge and Information Management Profession","k":"Rulebook: Skills and professions","u":"dam.html#RB-KIM","s":"Information, records and knowledge management; publishes a skills framework and runs communities for records officers."},{"t":"Government Security Profession","k":"Rulebook: Skills and professions","u":"dam.html#RB-SECPROF","s":"Security roles that work alongside data owners and the senior information risk owner."},{"t":"Government Cyber Profession","k":"Rulebook: Skills and professions","u":"dam.html#RB-CYBERPROF","s":"Cyber security careers aligned to the digital function."},{"t":"Success Profiles","k":"Rulebook: Skills and professions","u":"dam.html#RB-SUCCESS","s":"The recruitment framework; data responsibilities can be written into role descriptions and behaviours."},{"t":"SFIA 9: the global skills and competency framework for a digital world","k":"Rulebook: Skills and professions","u":"dam.html#RB-SFIA","s":"Industry skills framework with data management and governance skills; widely used alongside the government framework."},{"t":"Professional Knowledge and Skills Base (PKSB)","k":"Rulebook: Skills and professions","u":"dam.html#RB-PKSB","s":"Knowledge and skills for information professionals, including metadata, taxonomy and records."},{"t":"Royal Statistical Society professional development","k":"Rulebook: Skills and professions","u":"dam.html#RB-RSS","s":"Professional accreditation for statisticians and data scientists."},{"t":"Data analyst apprenticeship standard","k":"Rulebook: Skills and professions","u":"dam.html#RB-APPDA","s":"An entry route into data roles that public bodies can fund through the apprenticeship levy."},{"t":"DAMA-DMBOK: Data Management Body of Knowledge","k":"Rulebook: Skills and professions","u":"dam.html#RB-DAMA","s":"The most widely used body of knowledge for data management, with a professional certification (CDMP)."},{"t":"DCAM: Data Management Capability Assessment Model","k":"Rulebook: Skills and professions","u":"dam.html#RB-DCAM","s":"An industry capability assessment model for data management, used here only to cross-check coverage."},{"t":"Capability Maturity Model Integration (CMMI)","k":"Rulebook: Skills and professions","u":"dam.html#RB-CMMI","s":"The origin of the five-level maturity pattern most data maturity models use."},{"t":"Cyber Assessment Framework (CAF)","k":"Rulebook: Cyber and security","u":"dam.html#RB-CAF","s":"Outcome-based framework government uses to assess the cyber resilience of essential functions and the systems holding critical data."},{"t":"Government Cyber Security Strategy: 2022 to 2030","k":"Rulebook: Cyber and security","u":"dam.html#RB-GCSS","s":"Sets the aim for government organisations to be resilient to known vulnerabilities and attack methods, using the CAF."},{"t":"Government Functional Standard GovS 007: Security","k":"Rulebook: Cyber and security","u":"dam.html#RB-GOVS007","s":"The security functional standard, including information and cyber security, that data owners and the SIRO work within."},{"t":"Secure by design","k":"Rulebook: Cyber and security","u":"dam.html#RB-SBD","s":"Building security into digital services from the start, including the systems that create and hold critical data assets."},{"t":"10 Steps to Cyber Security","k":"Rulebook: Cyber and security","u":"dam.html#RB-NCSC10","s":"Practical cyber risk management areas, including asset management and incident management."},{"t":"Incident management","k":"Rulebook: Cyber and security","u":"dam.html#RB-NCSCIR","s":"Planning and handling cyber incidents, including those that corrupt or expose critical data."},{"t":"Cloud security guidance","k":"Rulebook: Cyber and security","u":"dam.html#RB-NCSCCLOUD","s":"How to choose and configure cloud services securely when critical data moves to them."},{"t":"Securing information in your service","k":"Rulebook: Cyber and security","u":"dam.html#RB-SECINFO","s":"How service teams protect the information their service holds."},{"t":"AI, open code and vulnerability risk in the public sector","k":"Rulebook: Cyber and security","u":"dam.html#RB-AICODE","s":"Risks when AI tools are used on open code, relevant to data pipelines and quality tooling."},{"t":"Government Cloud First policy","k":"Rulebook: Technology and architecture","u":"dam.html#RB-CLOUD","s":"Public cloud first for new or migrating services; data assets move with them."},{"t":"API catalogue","k":"Rulebook: Technology and architecture","u":"dam.html#RB-APICAT","s":"Lists APIs published by UK public sector organisations, grouped by owner. Search it for the APIs your organisation publishes when finding data already shared. A"},{"t":"API technical and data standards","k":"Rulebook: Technology and architecture","u":"dam.html#RB-API","s":"How to build and document APIs, the data services through which many critical data assets are reached."},{"t":"Develop your data and APIs using a reference architecture","k":"Rulebook: Technology and architecture","u":"dam.html#RB-REFARCH","s":"Reference architecture for data and APIs in government."},{"t":"Publish reference data for use across government","k":"Rulebook: Technology and architecture","u":"dam.html#RB-REFDATA","s":"How to publish reference data others can rely on, with a named owner, persistent identifiers, open formats and versioned change."},{"t":"Understanding accessibility requirements for public sector bodies","k":"Rulebook: Technology and architecture","u":"dam.html#RB-A11YREQ","s":"The accessibility regulations apply to the public sector's own websites and apps, including the interfaces staff use in data tools."},{"t":"Choosing technology: an introduction","k":"Rulebook: Technology and architecture","u":"dam.html#RB-CHOOSE","s":"How to choose technology that avoids lock-in and stays maintainable."},{"t":"Be open and use open source","k":"Rulebook: Technology and architecture","u":"dam.html#RB-OPENSRC","s":"Point 3 of the Technology Code of Practice; open code and open formats reduce future legacy."},{"t":"Model Services Contract","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-MSC","s":"The model contract for complex services, including schedules on data, security and exit."},{"t":"The Mid-Tier Contract: Schedule 20 (Processing Data)","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-MTC20","s":"Standard data processing terms for mid-tier contracts."},{"t":"Procurement Act 2023","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-PA23","s":"The law governing public procurement, including transparency notices that suppliers and buyers publish."},{"t":"Procurement Act 2023: guidance documents","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-PA23G","s":"Guidance for each phase of a procurement under the Act."},{"t":"G-Cloud 15 framework","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-GCLOUD","s":"The main route for buying cloud hosting, software and support, including catalogue and data quality tools."},{"t":"Government Commercial Function","k":"Rulebook: Skills and professions","u":"dam.html#RB-COMMFN","s":"The commercial profession, which buys the services and tools that hold critical data assets."},{"t":"Role of the senior responsible owner","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-SRO","s":"What a senior responsible owner is accountable for; data assets the programme touches fall within it."},{"t":"What each role does in a service team","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-SMROLES","s":"Service team roles, including the service owner and product manager who decide what data a service collects."},{"t":"How to join the Project Delivery Profession","k":"Rulebook: Skills and professions","u":"dam.html#RB-PDPROF","s":"The profession for programme and project leaders."},{"t":"Public Records Act 1958","k":"Rulebook: Records and information management","u":"dam.html#RB-PRA","s":"The legal duty to manage, select and transfer public records, which includes many data assets."},{"t":"Manage information: guidance for government","k":"Rulebook: Records and information management","u":"dam.html#RB-TNAIM","s":"Guidance on information and records management policy, processes, retention and digital records."},{"t":"Digital records transfer","k":"Rulebook: Records and information management","u":"dam.html#RB-TNATRANS","s":"How digital records, including data, are selected and transferred to The National Archives."},{"t":"ISO 15489-1:2016 Records management: concepts and principles","k":"Rulebook: Records and information management","u":"dam.html#RB-ISO15489","s":"The international records management standard. Its site blocks automated checking."},{"t":"ISO 23081-1:2017 Metadata for records: principles","k":"Rulebook: Records and information management","u":"dam.html#RB-ISO23081","s":"Records metadata principles, the records-management counterpart to catalogue metadata. Its site blocks automated checking."},{"t":"Data Standards Authority","k":"Rulebook: Data and AI","u":"dam.html#RB-DSA","s":"Sets and promotes the data standards organisations use to make data interoperable."},{"t":"Government Data Quality Hub","k":"Rulebook: Data and AI","u":"dam.html#RB-DQHUB","s":"Cross-government centre for data quality guidance, tools and support."},{"t":"Open Standards principles","k":"Rulebook: Technology and architecture","u":"dam.html#RB-OSP","s":"How government selects and uses open standards for software interoperability, data and document formats, including to avoid vendor lock-in."},{"t":"Technology Code of Practice point 4: make use of open standards","k":"Rulebook: Technology and architecture","u":"dam.html#RB-TCOP4","s":"What a plan must show about open standards and data to meet point 4, including avoiding lock-in."},{"t":"Technology Code of Practice point 11: define your purchasing strategy","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-TCOP11","s":"A purchasing strategy must show commercial and technology aspects and contractual limitations have been considered; it is checked in spend control."},{"t":"Managing technical lock-in in the cloud","k":"Rulebook: Technology and architecture","u":"dam.html#RB-LOCKIN","s":"Types of lock-in, weighing value against portability, and including exit cost and time in business cases."},{"t":"Procurement Policy Note 07/15: open standards for technology","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-PPN0715","s":"Tells buyers to specify open standards in technology procurements."},{"t":"Metadata standards for sharing and publishing data","k":"Rulebook: Data and AI","u":"dam.html#RB-METASTD","s":"The recommended metadata standards for sharing data within government and for publishing it."},{"t":"Data Standards Authority: Standards Catalogue","k":"Rulebook: Data and AI","u":"dam.html#RB-DSACAT","s":"The standards the Data Standards Authority has endorsed, with their status."},{"t":"Cloud services market investigation","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-CMACLOUD","s":"The CMA's final decision on public cloud infrastructure, covering egress fees, interoperability and software licensing."},{"t":"CMA announces package of actions on business software and cloud services","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-CMAPKG","s":"Follow-up actions to the cloud investigation, including commitments on egress fees and interoperability and a planned investigation into business software licen"},{"t":"EU Data Act (Regulation (EU) 2023/2854)","k":"Rulebook: Legislation","u":"dam.html#RB-EUDA","s":"Switching rules for cloud and other data processing services supplied into the EU, phasing out switching charges. Applies to services supplied into the EU, not "},{"t":"Find a Tender","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-FTS","s":"Where public procurement notices are published; search it for other bodies' catalogue, data quality and data platform requirements."},{"t":"Digital Marketplace: search G-Cloud services","k":"Rulebook: Commercial and procurement","u":"dam.html#RB-GCSEARCH","s":"Service descriptions on G-Cloud include standards, APIs and how buyers can get their data out at the end of a contract."},{"t":"PROV-O: the PROV ontology","k":"Rulebook: Standards","u":"dam.html#RB-PROVO","s":"An open vocabulary for provenance, used to describe where data came from and what was done to it."},{"t":"SKOS: Simple Knowledge Organization System reference","k":"Rulebook: Standards","u":"dam.html#RB-SKOS","s":"The open format for glossaries, thesauri and taxonomies, so business terms can move between tools."},{"t":"CSV on the Web (CSVW) primer","k":"Rulebook: Standards","u":"dam.html#RB-CSVW","s":"Describes the columns, types and constraints of CSV files, so files carry their own data dictionary."},{"t":"OpenLineage","k":"Rulebook: Standards","u":"dam.html#RB-OLINEAGE","s":"An open specification for lineage events from running jobs, so lineage can be collected once and read by several tools."},{"t":"Open Data Contract Standard (ODCS)","k":"Rulebook: Standards","u":"dam.html#RB-ODCS","s":"An open format for data contracts, including schema, quality rules and service levels, readable by more than one tool."},{"t":"Open Data Product Standard (ODPS)","k":"Rulebook: Standards","u":"dam.html#RB-ODPS","s":"An open format describing data products, designed to reference data contracts."},{"t":"Egeria open metadata and governance","k":"Rulebook: Standards","u":"dam.html#RB-EGERIA","s":"An open source project for exchanging metadata between tools from different vendors; useful as a reference for open metadata types and connectors."},{"t":"OpenAPI Specification","k":"Rulebook: Standards","u":"dam.html#RB-OAS","s":"The open format for describing REST APIs; government API guidance recommends it."},{"t":"Model Context Protocol","k":"Rulebook: Standards","u":"dam.html#RB-MCPSPEC","s":"An open protocol for connecting AI assistants to tools and data, such as a catalogue."},{"t":"A roadmap for modern digital government 2025 to 2030","k":"Rulebook: Delivery, change and investment","u":"dam.html#RB-RMDG","s":"The government's action plan to 2030, with six priorities, from joining up public services to transparency and accountability."},{"t":"Service Manual: finding participants for user research","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-SMUR","s":"Participants must be actual or likely users, and research must include disabled people."},{"t":"Service Manual: getting informed consent for user research","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-SMCONSENT","s":"Every participant gives informed consent, even colleagues in the same organisation."},{"t":"Service Manual: managing user research data and participant privacy","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-SMPRIVACY","s":"How to collect, store and delete participants' personal data."},{"t":"Service Manual: running research sessions with disabled people","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-SMDISABLED","s":"Planning sessions that work for disabled participants and their assistive technology."},{"t":"data.gov.uk roadmap","k":"Rulebook: Data and AI","u":"dam.html#RB-DGUROADMAP","s":"A public Now, Next, Later roadmap with feedback routes; the model this portal's roadmap follows."},{"t":"ISO 8601-1:2019 Date and time: representations for information interchange","k":"Rulebook: Standards","u":"dam.html#RB-ISO8601","s":"The date format the metadata guidance asks for, for example 2026-11-12."},{"t":"ISO 3166-1:2020 Country codes","k":"Rulebook: Standards","u":"dam.html#RB-ISO3166","s":"One list of country codes across every service, so country fields can be joined."},{"t":"ISO 4217 Currency codes","k":"Rulebook: Standards","u":"dam.html#RB-ISO4217","s":"Three-letter currency codes for spend and payments data."},{"t":"Names and codes listings (GSS geography codes)","k":"Rulebook: Geospatial","u":"dam.html#RB-ONSGEO","s":"Definitive nine-character codes and names for UK statistical and administrative geographies."},{"t":"Harmonised standards and guidance","k":"Rulebook: Statistics","u":"dam.html#RB-GSSHARM","s":"Shared definitions and questions for topics such as age, sex, ethnicity and language, so statistics are comparable."},{"t":"Shapes Constraint Language (SHACL)","k":"Rulebook: Standards","u":"dam.html#RB-SHACL","s":"Rules that check linked data, such as catalogue records or vocabularies, before they are published."},{"t":"Timelines for migration to post-quantum cryptography","k":"Rulebook: Cyber and security","u":"dam.html#RB-NCSCPQC","s":"Discovery and an initial plan by 2028, priority migration by 2031 and all systems by 2035. Knowing which critical assets depend on cryptography is the discovery"},{"t":"Service Standard point 13: use and contribute to open standards, common components and patterns","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-SVC13","s":"The Service Standard point closest to data assets: open standards, APIs and authoritative data sources. It does not mention metadata or catalogues."},{"t":"Technology Code of Practice point 10: make better use of data","k":"Rulebook: Technology and architecture","u":"dam.html#RB-TCOP10","s":"Plan for the whole data lifecycle and use government metadata standards. It does not yet name the DAM Policy."},{"t":"Government technology standards and guidance","k":"Rulebook: Technology and architecture","u":"dam.html#RB-TECHSTDS","s":"The index of standards and guidance for government technology. It does not yet list the DAM collection."},{"t":"Principles for securing personal data in government services","k":"Rulebook: Cyber and security","u":"dam.html#RB-SECPD","s":"Starts by asking service teams to identify their data assets, which is where critical data assets are first found."},{"t":"Follow the Government Cyber Security Standard","k":"Rulebook: Cyber and security","u":"dam.html#RB-CYBERSTD","s":"How government organisations protect their assets, including the systems that hold critical data assets."},{"t":"The role of information asset owners in government","k":"Rulebook: Records and information management","u":"dam.html#RB-IAO","s":"The information asset owner role, which the data owner role sits beside. It points readers to the data ownership model."},{"t":"Code of Practice on the Management of Records issued under section 46 of the Freedom of Information Act 2000","k":"Rulebook: Records and information management","u":"dam.html#RB-S46","s":"The statutory code for keeping, retaining and disposing of records, including critical data assets and their metadata."},{"t":"Record information about data sets you share with others","k":"Rulebook: Data and AI","u":"dam.html#RB-RECINFO","s":"Older metadata guidance that overlaps the guidance on recording metadata for critical data assets."},{"t":"Service Manual: data management community","k":"Rulebook: Service delivery and technology","u":"dam.html#RB-DMCOMM","s":"The cross-government data management community. The only GOV.UK page outside the DAM collection found linking to the policy."},{"t":"F-01 Issues framework Table 4 contradicts its own rule for a 97.5% target","k":"Verification finding","u":"about.html#F-01","s":"The framework says the High band starts halfway between the Middle band start and the target. For a 97.5% target the Middle band starts at 95%, so the High band"},{"t":"F-02 The Data Ethics Framework is now the Data and AI Ethics Framework","k":"Verification finding","u":"about.html#F-02","s":"The GOV.UK page at the Data Ethics Framework address is titled 'Data and AI Ethics Framework' (updated 18 December 2025)."},{"t":"F-03 The GOV.UK style guide has moved","k":"Verification finding","u":"about.html#F-03","s":"The style guide and 'writing for GOV.UK' addresses on GOV.UK now redirect to guidance.publishing.service.gov.uk."},{"t":"F-05 The government data maturity framework uses a licence this portal cannot carry","k":"Verification finding","u":"about.html#F-05","s":"The Data Maturity Assessment for Government framework is published under CC BY-NC-SA 4.0, not the Open Government Licence, and asks government users to contact "},{"t":"F-06 Legacy technology guidance asks for a data asset register but does not mention the DAM Policy","k":"Verification finding","u":"about.html#F-06","s":"The second principle of 'Managing legacy technology' (updated 15 October 2026) is to build a complete and accurate register of your data assets. The DAM Policy "},{"t":"F-07 The government learning platform is not yet fully accessible","k":"Verification finding","u":"about.html#F-07","s":"The Government Skills Campus accessibility statement (last updated 14 April 2026) says some parts do not meet WCAG 2.2 AA, with compliance aimed for by the end "},{"t":"F-04 Four metadata properties have no slot in the Metadata Exchange Model","k":"Verification finding","u":"about.html#F-04","s":"temporalCoverage, conformsTo, expires and supersededBy appear in the GOV.UK metadata guidance but not in the published MEM classes."},{"t":"F-08 The superseded essential shared data assets guide is still published","k":"Verification finding","u":"about.html#F-08","s":"'Make essential shared data assets available across government' (last updated 23 February 2024) is still live on GOV.UK. It is not withdrawn and does not redire"},{"t":"F-09 The old 'Data ownership in government' address sends readers to the wrong page","k":"Verification finding","u":"about.html#F-09","s":"The ESDA-era address for 'Data ownership in government' now redirects to the guidance on identifying critical data assets, not to the data ownership model. The "},{"t":"F-10 Four live GOV.UK pages still use the essential shared data assets wording","k":"Verification finding","u":"about.html#F-10","s":"The Data and AI Ethics Framework, 'Using metadata to describe data assets in a data catalogue', 'Principles for securing personal data in government services' a"},{"t":"F-11 Almost no GOV.UK guidance links to the DAM Policy","k":"Verification finding","u":"about.html#F-11","s":"Of 609 GOV.UK pages read on 20 November 2026, only the Service Manual's data management community page links to the policy from outside the DAM collection. GovS"},{"t":"F-12 The DAM guidance links unofficial and commercial sources","k":"Verification finding","u":"about.html#F-12","s":"The data ownership model links an unofficial GDPR text site rather than legislation.gov.uk. The metadata guidance links Wikipedia. The data quality action plan "},{"t":"XR-01 Make essential shared data assets available across government","k":"Cross-reference","u":"dam.html#XR-01","s":"Guidance for the policy the DAM Policy replaced. It is still published, not withdrawn or redirected."},{"t":"XR-02 Old address of 'Data ownership in government'","k":"Cross-reference","u":"dam.html#XR-02","s":"Redirects to the guidance on identifying critical data assets, not to the data ownership model. The DAM guidance and the information asset owner guidance both l"},{"t":"XR-03 Data and AI Ethics Framework","k":"Cross-reference","u":"dam.html#XR-03","s":"Tells teams to register data assets by designating essential shared data assets."},{"t":"XR-04 Using metadata to describe data assets in a data catalogue","k":"Cross-reference","u":"dam.html#XR-04","s":"Recommends DCAT 'particularly' for essential shared data assets."},{"t":"XR-05 Principles for securing personal data in government services","k":"Cross-reference","u":"dam.html#XR-05","s":"Asks teams to consider designating an essential shared data asset."},{"t":"XR-06 Government Functional Standard GovS 005: Digital","k":"Cross-reference","u":"dam.html#XR-06","s":"Version 2.2 names the policy in section 7.5 without a link. Its continuous improvement assessment framework still speaks of essential shared data assets."},{"t":"XR-07 Data quality action plan implementation guide","k":"Cross-reference","u":"dam.html#XR-07","s":"The DAM guidance links an unofficial GDPR text site, Wikipedia and a supplier's PDF, and two of its pages use the old DQAP address."},{"t":"XR-08 Service Standard point 13: use and contribute to open standards, common components and patterns","k":"Cross-reference","u":"dam.html#XR-08","s":"None of the 14 points mentions metadata, data catalogues or data ownership. Point 13 comes closest."},{"t":"XR-09 Technology Code of Practice point 10: make better use of data","k":"Cross-reference","u":"dam.html#XR-09","s":"Mentions government metadata standards but not the policy or critical data assets."},{"t":"XR-10 Government technology standards and guidance","k":"Cross-reference","u":"dam.html#XR-10","s":"Lists technology standards and guidance, but not the DAM collection."},{"t":"XR-11 The Government Data Quality Framework","k":"Cross-reference","u":"dam.html#XR-11","s":"Predates the policy, so it does not mention data quality action plans for critical data assets."},{"t":"XR-12 Data Sharing Governance Framework","k":"Cross-reference","u":"dam.html#XR-12","s":"Asks organisations to make sure people can discover what data they hold, without naming the policy or its catalogue duty."},{"t":"XR-13 Making government datasets ready for AI","k":"Cross-reference","u":"dam.html#XR-13","s":"Covers data and metadata quality for AI without citing the policy, and the DAM guidance does not cite it either."},{"t":"XR-14 The role of information asset owners in government","k":"Cross-reference","u":"dam.html#XR-14","s":"Points to the data ownership model through the old address (XR-02), so readers land on the wrong page. Does not name the policy."},{"t":"XR-15 Data Maturity Assessment for Government: Framework","k":"Cross-reference","u":"dam.html#XR-15","s":"Uses 'critical data assets' in its security levels without naming or linking the policy."},{"t":"XR-16 Record information about data sets you share with others","k":"Cross-reference","u":"dam.html#XR-16","s":"Older metadata guidance that overlaps the guidance on recording metadata for critical data assets."},{"t":"XR-17 AI Playbook for the UK Government","k":"Cross-reference","u":"dam.html#XR-17","s":"Covers data for AI systems without citing data ownership or data quality action plans."},{"t":"XR-18 API technical and data standards","k":"Cross-reference","u":"dam.html#XR-18","s":"Does not link the metadata guidance, though a data service can be part of a data asset."},{"t":"XR-19 Publish reference data for use across government","k":"Cross-reference","u":"dam.html#XR-19","s":"Names a reference data owner and steward without the data ownership model."},{"t":"XR-20 Data Standards Authority: Standards Catalogue","k":"Cross-reference","u":"dam.html#XR-20","s":"Lists data standards but not the metadata guidance for critical data assets."},{"t":"XR-21 Government Security Classifications","k":"Cross-reference","u":"dam.html#XR-21","s":"The policy covers OFFICIAL assets only, but its guidance does not link the classification policy."},{"t":"XR-22 Code of Practice on the Management of Records issued under section 46 of the Freedom of Information Act 2000","k":"Cross-reference","u":"dam.html#XR-22","s":"Retention and disposal of critical data assets and their metadata are not covered by the DAM guidance."},{"t":"XR-23 The Orange Book: management of risk","k":"Cross-reference","u":"dam.html#XR-23","s":"The DQAP guide and issues framework deal in risk without citing government risk management guidance."},{"t":"XR-24 Follow the Government Cyber Security Standard","k":"Cross-reference","u":"dam.html#XR-24","s":"The guidance does not link the cyber security standard that protects the systems holding critical data assets."},{"t":"XR-25 The AQuA Book","k":"Cross-reference","u":"dam.html#XR-25","s":"Where critical data assets feed analysis, quality assurance of that analysis is not linked."},{"t":"XR-26 Service Manual: data management community","k":"Cross-reference","u":"dam.html#XR-26","s":"Links the policy."},{"t":"XR-27 State of digital government review","k":"Cross-reference","u":"dam.html#XR-27","s":"Mentions essential shared data assets as history, which is right for its date."},{"t":"FR-01 Show every DAM Policy requirement with its strength, source and the step that meets it.","k":"Portal requirement","u":"design.html#FR-01","s":""},{"t":"FR-02 Give a step-by-step method for each capability with roles, templates and measures.","k":"Portal requirement","u":"design.html#FR-02","s":""},{"t":"FR-03 Offer a route and learning journey for each role, with progress the reader controls.","k":"Portal requirement","u":"design.html#FR-03","s":""},{"t":"FR-04 Let anyone get in touch without an email address being published.","k":"Portal requirement","u":"design.html#FR-04","s":""},{"t":"FR-05 Let readers search everything and filter every list.","k":"Portal requirement","u":"design.html#FR-05","s":""},{"t":"FR-06 Publish the vocabulary, requirements and templates as open data.","k":"Portal requirement","u":"design.html#FR-06","s":""},{"t":"NFR-01 Meet WCAG 2.2 AA in light and dark modes, from 320 to 1920 pixels wide.","k":"Portal requirement","u":"design.html#NFR-01","s":""},{"t":"NFR-02 Work with scripts turned off and load nothing from other sites.","k":"Portal requirement","u":"design.html#NFR-02","s":""},{"t":"NFR-03 Label every fact with its provenance and keep sources current.","k":"Portal requirement","u":"design.html#NFR-03","s":""},{"t":"NFR-04 Name roles, never people, and hold no personal data.","k":"Portal requirement","u":"design.html#NFR-04","s":""},{"t":"NFR-05 Be findable by search engines with accurate descriptions.","k":"Portal requirement","u":"design.html#NFR-05","s":""},{"t":"TR-01 Generate every page from one content file and refuse to build on a broken reference.","k":"Portal requirement","u":"design.html#TR-01","s":""},{"t":"FR-07 Show every capability the policy and adjacent guidance need, flagged explicit, implicit or inferred, with a signpost to the section it comes from.","k":"Portal requirement","u":"design.html#FR-07","s":""},{"t":"FR-08 Let organisations assess their maturity against the government model and DAM strands, keep the answers privately and download them.","k":"Portal requirement","u":"design.html#FR-08","s":""},{"t":"FR-09 Link each role in the policy to government professions, framework roles, skills and learning routes.","k":"Portal requirement","u":"design.html#FR-09","s":""},{"t":"FR-10 Help organisations embed the policy in business as usual and in change programmes, with actions they can track.","k":"Portal requirement","u":"design.html#FR-10","s":""},{"t":"FR-11 Help readers find which sector supplements apply to an asset.","k":"Portal requirement","u":"design.html#FR-11","s":""},{"t":"FR-12 Help readers find their way: a share menu on every page, a site map, a user guide with guided tours and tutorials.","k":"Portal requirement","u":"design.html#FR-12","s":""},{"t":"FR-13 Let organisations reuse the content through links, embedding, open data, AI assistants and an MCP server.","k":"Portal requirement","u":"design.html#FR-13","s":""},{"t":"FR-14 Help organisations connect and buy data management tools without lock-in, with open standards and RFI questions.","k":"Portal requirement","u":"design.html#FR-14","s":""},{"t":"FR-15 Signpost the sister portals where they help, naming each and its status, without merging their journeys or copying their content.","k":"Portal requirement","u":"design.html#FR-15","s":""},{"t":"FR-16 Help people who work across the three portals choose where to start, in what order and why, without merging the portals.","k":"Portal requirement","u":"design.html#FR-16","s":""},{"t":"FR-17 Let users take part in research privately, suggest and vote for ideas, and see the roadmap, backlog and how each item is prioritised against government strategy, in the open.","k":"Portal requirement","u":"design.html#FR-17","s":""},{"t":"FR-18 Let teams name people and work email addresses in their own copies of templates, and keep them out of anything published.","k":"Portal requirement","u":"design.html#FR-18","s":""},{"t":"FR-19 Say whether each template is for business as usual, change or both, offer each template on its own, and offer logs used together as one tabbed workbook.","k":"Portal requirement","u":"design.html#FR-19","s":""},{"t":"FR-20 Give the data type, format, cardinality, controlled values and an example for every catalogue record property.","k":"Portal requirement","u":"design.html#FR-20","s":""},{"t":"FR-21 Group each sector supplement's legislation, standards and frameworks by kind, and show how sector standards meet the catalogue standard.","k":"Portal requirement","u":"design.html#FR-21","s":""},{"t":"FR-22 Describe a critical data asset's entities, relationships and authoritative source, with a relationship diagram drawn from the list (issue 18).","k":"Portal requirement","u":"design.html#FR-22","s":""},{"t":"FR-23 Record retention schedule, period and disposal action in the ownership register and catalogue record, from the organisation's own schedule (issue 19).","k":"Portal requirement","u":"design.html#FR-23","s":""},{"t":"FR-24 Give a data sharing agreement template covering lawful basis, legal gateway, retention and ending the sharing, and signpost the gateways (issue 20).","k":"Portal requirement","u":"design.html#FR-24","s":""},{"t":"FR-25 Show governance layers with the roles in each and what each may and may not change (issue 21).","k":"Portal requirement","u":"design.html#FR-25","s":""},{"t":"FR-26 Signpost health confidentiality gateways and medical device rules in the health and care supplement (issue 22).","k":"Portal requirement","u":"design.html#FR-26","s":""},{"t":"FR-27 Give glossary terms and named frameworks, methodologies and standards a tooltip and a link where they are first mentioned on any page, outside headings and existing links.","k":"Portal requirement","u":"design.html#FR-27","s":""},{"t":"FR-28 List each capability's frameworks, methodologies and standards by kind on its Overview, and name the ones that apply at every step.","k":"Portal requirement","u":"design.html#FR-28","s":""},{"t":"FR-29 Drill down from each slice of the DAMA wheel to its activities and tasks where the portal has them, and publish what a fuller drill-down and a data architecture playbook would take (BL-35, BL-36).","k":"Portal requirement","u":"design.html#FR-29","s":""},{"t":"FR-30 Take every capability in the capability model down to activities with steps, outputs, evidence, measures, who does what and a template.","k":"Portal requirement","u":"design.html#FR-30","s":""},{"t":"FR-31 Give people new to data asset management, or leading it, aims by priority, outcomes with indicators, and a plan for 30, 60 and 90 days with 6 and 12 month checkpoints against maturity levels.","k":"Portal requirement","u":"design.html#FR-31","s":""},{"t":"FR-32 Reach the data portals compass and the asset governance explorer from every page, and keep the capabilities they show the same as the capability model.","k":"Portal requirement","u":"design.html#FR-32","s":""},{"t":"FR-33 Give ready-made functional and non-functional requirements for each kind of tool, with a request for information, a requirements schedule, an evaluation method and contract clauses.","k":"Portal requirement","u":"design.html#FR-33","s":""},{"t":"FR-34 Help learners learn, keep and share what they learn, link it to roles, careers and certifications, and download a learning record to use as CPD evidence.","k":"Portal requirement","u":"design.html#FR-34","s":""},{"t":"FR-35 Recommend modules, activities and the next checkpoint by role, profession, organisation maturity and data literacy, reading the self-assessment where there is one.","k":"Portal requirement","u":"design.html#FR-35","s":""},{"t":"FR-36 For every stage of designing and delivering a service, show the gates and assessments, the Service Standard points that touch critical data, what reviewers want to see and where the evidence comes from, linking to published guidance rather than repeating it.","k":"Portal requirement","u":"design.html#FR-36","s":""},{"t":"FR-37 Show which GOV.UK guidance should point to the DAM Policy and which guidance the DAM guidance should point to, with stale references to fix, each linked to the exact section and checked against GOV.UK.","k":"Portal requirement","u":"design.html#FR-37","s":""},{"t":"IR-01 Use only GitHub services (Pages, issue forms, Discussions, Actions and releases), plus an optional Microsoft Forms route for private feedback.","k":"Portal requirement","u":"design.html#IR-01","s":""},{"t":"OR-01","k":"Open register","u":"about.html#OR-01","s":"The internal Data Cataloguing Playbook v2.6 is not public. The cataloguing stages here are a synthesis of GOV.UK guidance and need checking against it, or repla"},{"t":"OR-02","k":"Open register","u":"about.html#OR-02","s":"Added on 5 November 2026: a private Microsoft Forms route, so people without a GitHub account can give feedback. Set on 8 November 2026: anyone can respond with"},{"t":"OR-03","k":"Open register","u":"about.html#OR-03","s":"Not cleared as official guidance. Clearance, and a move to an official GitHub organisation, are needed before departments are told to rely on it."},{"t":"OR-04","k":"Open register","u":"about.html#OR-04","s":"No research with real users yet. A research plan with questions, methods, hypotheses and falsification conditions is now published on the Service design page; i"},{"t":"OR-05","k":"Open register","u":"about.html#OR-05","s":"The policy promises minimum interoperability requirements that its body does not state. The Tools and interoperability page proposes open standards for each bou"},{"t":"OR-06","k":"Open register","u":"about.html#OR-06","s":"Four metadata properties in the guidance have no slot in the published MEM. A crosswalk to DCAT and Dublin Core terms is proposed on the cataloguing page (findi"},{"t":"OR-07","k":"Open register","u":"about.html#OR-07","s":"Dates for the rollout phases, returns and support offer come from practitioner material, not a public page. Confirm before external use."},{"t":"OR-08","k":"Open register","u":"about.html#OR-08","s":"The governance escalation timescales are this playbook's recommendation. Each organisation should set its own."},{"t":"OR-09","k":"Open register","u":"about.html#OR-09","s":"Not tested with disabled users or assistive technology users in person; automated checks only."},{"t":"OR-10","k":"Open register","u":"about.html#OR-10","s":"Data owner versus information asset owner is resolved by the GOV.UK data ownership model (three options). The two maturity models and the remaining glossary con"},{"t":"OR-12","k":"Open register","u":"about.html#OR-12","s":"All 14 sector themes now have supplements on the Sectors page, signposted from each capability playbook. Each supplement is this portal's synthesis and needs re"},{"t":"OR-13","k":"Open register","u":"about.html#OR-13","s":"Done on 5 November 2026: description, homepage, topics, Discussions, private vulnerability reporting, Dependabot, secret push protection and approval for workfl"},{"t":"OR-14","k":"Open register","u":"about.html#OR-14","s":"The Data Maturity Assessment framework is CC BY-NC-SA 4.0 and asks government users to contact CDDO. Confirm whether its level descriptions may be shown inside "},{"t":"OR-15","k":"Open register","u":"about.html#OR-15","s":"The explicit, implicit and inferred flags on the capability model are this portal's reading of the policy. Ask the GDS data policy team to confirm them, especia"},{"t":"OR-16","k":"Open register","u":"about.html#OR-16","s":"Done on 5 November 2026: Pages publishes the built site from the gh-pages branch. Still to do: set the default workflow token to read-only and stop GitHub Actio"},{"t":"OR-17","k":"Open register","u":"about.html#OR-17","s":"Decide whether to rewrite the four commits credited to the unrelated 'noreply' account (D-021). It removes the false credit but changes their identifiers and ne"},{"t":"OR-18","k":"Open register","u":"about.html#OR-18","s":"Decide which glossary is master. The compendium glossary (LIB-18), this portal's knowledge layer and the cross-portfolio shared glossary kept with the data asse"},{"t":"OR-11","k":"Open register","u":"about.html#OR-11","s":"Verified on GOV.UK: Table 4 of the issues framework contradicts its own rule for a 97.5% target (finding F-01). Raise with the GDS data quality team; tracked as"},{"t":"CR-01 Accountable leadership and policy oversight","k":"Capability (explicit)","u":"capability-model.html#CR-01","s":"Each organisation's chief data officer is responsible for implementing the policy; the Chief Data Officer Council oversees it."},{"t":"CR-02 Data strategy and prioritisation by reuse value","k":"Capability (implicit)","u":"capability-model.html#CR-02","s":"The policy expects organisations to start with assets of proven reuse value, which needs a way to rank assets that the policy does not spell out."},{"t":"CR-03 Central reporting, assurance and arm's length body coordination","k":"Capability (explicit)","u":"capability-model.html#CR-03","s":"Departments report their assets to GDS and coordinate and assure the returns of their arm's length bodies."},{"t":"CR-04 Performance measurement and annual review","k":"Capability (explicit)","u":"capability-model.html#CR-04","s":"Returns must be maintained and reviewed every year; the guidance adds measures for ownership and quality."},{"t":"CR-05 Identify and scope critical data assets","k":"Capability (explicit)","u":"capability-model.html#CR-05","s":"Only assets classified OFFICIAL are in scope, and the critical-asset guidance defines which assets count."},{"t":"CR-06 Data cataloguing and metadata management","k":"Capability (explicit)","u":"capability-model.html#CR-06","s":"Metadata about in-scope assets must be held in a data catalogue; the quality guide also assumes a catalogue exists."},{"t":"CR-07 Data ownership and stewardship","k":"Capability (explicit)","u":"capability-model.html#CR-07","s":"Every identified asset must have a named data owner, as set out in the data ownership model."},{"t":"CR-08 Data quality management through action plans","k":"Capability (explicit)","u":"capability-model.html#CR-08","s":"Every identified asset must have a data quality action plan or an equivalent that covers all 7 steps."},{"t":"CR-09 Data quality issue management","k":"Capability (implicit)","u":"capability-model.html#CR-09","s":"The policy points to the issues framework to support resource decisions; logging and prioritising issues is how plans turn into action."},{"t":"CR-10 Data life cycle management","k":"Capability (explicit)","u":"capability-model.html#CR-10","s":"The policy sets out life cycle controls; the ownership model makes life cycle management a principle."},{"t":"CR-11 Interoperability, data standards and identifiers","k":"Capability (explicit)","u":"capability-model.html#CR-11","s":"The policy sets minimum requirements for interoperability; standards and shared identifiers are how they are met."},{"t":"CR-12 Data architecture and data services","k":"Capability (implicit)","u":"capability-model.html#CR-12","s":"A data asset includes the data services (such as APIs) used to reach it, so someone must design and run those services."},{"t":"CR-13 Catalogue and quality tooling","k":"Capability (implicit)","u":"capability-model.html#CR-13","s":"Catalogues and automated quality checks need platforms; GDS will build a central discovery service."},{"t":"CR-14 Reference data, master data and authoritative sources","k":"Capability (implicit)","u":"capability-model.html#CR-14","s":"Reducing duplicate collection depends on agreeing which source is authoritative; the policy states the aim, the ownership model the principle."},{"t":"CR-15 Records, retention and disposal","k":"Capability (inferred)","u":"capability-model.html#CR-15","s":"Not mentioned in the policy, but an asset's life cycle ends in retention, transfer or disposal, which records law governs."},{"t":"CR-16 Security classification and protective controls","k":"Capability (explicit)","u":"capability-model.html#CR-16","s":"Scope depends on classification (OFFICIAL only), so classification must be right before an asset is recorded."},{"t":"CR-17 Data protection and lawful sharing","k":"Capability (explicit)","u":"capability-model.html#CR-17","s":"The policy keeps every legal and data protection obligation in place and does not force sharing."},{"t":"CR-18 AI readiness and data and AI ethics","k":"Capability (explicit)","u":"capability-model.html#CR-18","s":"The policy names AI readiness as a reason for quality plans; ethics is not named, so it is inferred from the AI guidance."},{"t":"CR-19 Data risk management","k":"Capability (explicit)","u":"capability-model.html#CR-19","s":"The policy cites risk controls and understanding cross-public sector dependencies to manage risk; how is left to each organisation."},{"t":"CR-20 Third-party and supplier data","k":"Capability (implicit)","u":"capability-model.html#CR-20","s":"Many critical assets are held or processed by suppliers; ownership, metadata and quality duties must reach into contracts."},{"t":"CR-21 Data skills, capability and literacy","k":"Capability (implicit)","u":"capability-model.html#CR-21","s":"The policy assigns new responsibilities; the guidance lists the skills and training those people need."},{"t":"CR-22 Data culture and engagement with users","k":"Capability (implicit)","u":"capability-model.html#CR-22","s":"Ownership and quality only last where people value data and know who uses it."},{"t":"CR-23 Maturity assessment and continuous improvement","k":"Capability (implicit)","u":"capability-model.html#CR-23","s":"The policy recognises different levels of data maturity; the government maturity framework is the shared way to measure them."},{"t":"CR-24 Investment, business cases and value","k":"Capability (explicit)","u":"capability-model.html#CR-24","s":"The policy says data must be properly valued and invested in; funding comes through business cases."},{"t":"CR-25 Integration with programmes, spend control and assurance","k":"Capability (inferred)","u":"capability-model.html#CR-25","s":"Not in the policy text. Most new and replacement data assets arrive through change programmes, so the controls must be built into them."},{"t":"CR-26 Legacy migration and decommissioning","k":"Capability (inferred)","u":"capability-model.html#CR-26","s":"Not in the policy. The legacy guidance makes a data asset register its second principle; migrations are where quality is most at risk."},{"t":"CR-27 Ownership transition and handover to business as usual","k":"Capability (implicit)","u":"capability-model.html#CR-27","s":"A named owner must survive staff moves and the end of the project that created the asset."},{"t":"CR-28 Cross-boundary collaboration","k":"Capability (explicit)","u":"capability-model.html#CR-28","s":"Departments coordinate with their arm's length bodies, and data passed to devolved administrations can stay in scope."},{"t":"CR-29 Benefits realisation and evaluation","k":"Capability (inferred)","u":"capability-model.html#CR-29","s":"The policy lists benefits such as less duplication and cleansing; showing they happened needs an evaluation plan."},{"t":"CR-30 Equality and inclusion in data","k":"Capability (inferred)","u":"capability-model.html#CR-30","s":"Not in the policy, but the equality duty applies to decisions about which assets to fix first, and poor data about some groups widens inequality."},{"t":"CR-31 Cyber resilience and incident response for data assets","k":"Capability (implicit)","u":"capability-model.html#CR-31","s":"The policy scopes assets by classification and the ownership model makes security a principle, but neither says how to protect a critical asset from, or recover"},{"t":"CR-32 Avoiding future legacy: open standards, portability and exit","k":"Capability (inferred)","u":"capability-model.html#CR-32","s":"Not in the policy. Without open formats, documented schemas and exit terms, every new system becomes the next concentration of hard-to-reach data."},{"t":"Maturity topic 1: Engaging with others","k":"Data maturity model","u":"capability-model.html#cm-maturity","s":""},{"t":"Maturity topic 2: Having the right data skills and knowledge","k":"Data maturity model","u":"capability-model.html#cm-maturity","s":""},{"t":"Maturity topic 3: Having the right systems","k":"Data maturity model","u":"capability-model.html#cm-maturity","s":""},{"t":"Maturity topic 4: Knowing the data you have","k":"Data maturity model","u":"capability-model.html#cm-maturity","s":""},{"t":"Maturity topic 5: Making decisions with data","k":"Data maturity model","u":"capability-model.html#cm-maturity","s":""},{"t":"Maturity topic 6: Managing and using data ethically","k":"Data maturity model","u":"capability-model.html#cm-maturity","s":""},{"t":"Maturity topic 7: Managing your data","k":"Data maturity model","u":"capability-model.html#cm-maturity","s":""},{"t":"Maturity topic 8: Protecting your data","k":"Data maturity model","u":"capability-model.html#cm-maturity","s":""},{"t":"Maturity topic 9: Setting your data direction","k":"Data maturity model","u":"capability-model.html#cm-maturity","s":""},{"t":"Maturity topic 10: Taking responsibility for data","k":"Data maturity model","u":"capability-model.html#cm-maturity","s":""},{"t":"Data governance manager","k":"Career pathway","u":"professions.html#role-data-governance-manager","s":"Communicating analysis and insight Communicating between the technical and non-technical Data ethics and privacy Data governance Data innovation Data life cycle"},{"t":"Chief data officer","k":"Career pathway","u":"professions.html#role-chief-data-officer","s":"Capability building for digital, data and technology Data architecture Data governance leadership Data risk management Innovation in digital, data and technolog"},{"t":"Data architect","k":"Career pathway","u":"professions.html#role-data-architect","s":"Communicating between the technical and non-technical Communicating data Data analysis and synthesis Data governance (data architect) Data innovation Data model"},{"t":"Data analyst","k":"Career pathway","u":"professions.html#role-data-analyst","s":"Applying statistical and analytical tools and techniques Communicating between the technical and non-technical Data ethics and privacy Data management Data prep"},{"t":"Data engineer","k":"Career pathway","u":"professions.html#role-data-engineer","s":"Communicating between the technical and non-technical Data analysis and synthesis Data compliance and security Data development process Data innovation Data int"},{"t":"Data and artificial intelligence (AI) ethicist","k":"Career pathway","u":"professions.html#role-data-and-ai-ethicist","s":"Analysis and synthesis for data and AI ethics Applied empathy and inclusivity Applied social sciences Communicating between the technical and non-technical Data"},{"t":"Performance analyst","k":"Career pathway","u":"professions.html#role-performance-analyst","s":"Analysis and insight Communicating analysis and insight Performance measurement Quality assurance of data and analysis Technical understanding (performance anal"},{"t":"Government Digital and Data Profession","k":"Profession","u":"professions.html#PR-DD","s":"Home of the data governance manager, data architect, analyst, engineer and chief data officer roles."},{"t":"Analysis Function (statistics, economics, social and operational research, geography, actuaries)","k":"Profession","u":"professions.html#PR-AF","s":"Analysts who own and assure data for statistics, evidence and evaluation."},{"t":"Knowledge and Information Management","k":"Profession","u":"professions.html#PR-KIM","s":"Records, information assets, metadata and information asset owner support."},{"t":"Government Security Profession","k":"Profession","u":"professions.html#PR-SEC","s":"Classification, protective controls and support to the senior information risk owner."},{"t":"Government Cyber Profession","k":"Profession","u":"professions.html#PR-CYB","s":"Technical security of the systems that hold critical assets."},{"t":"Project Delivery","k":"Profession","u":"professions.html#PR-PD","s":"Senior responsible owners and programme teams who create, migrate and retire data assets."},{"t":"The data owner's own profession (for example policy, operational delivery or finance)","k":"Profession","u":"professions.html#PR-OWNPROF","s":"Data owners are usually business leaders, not data specialists; the ownership model lists the skills they need."},{"t":"Government Commercial Function","k":"Profession","u":"professions.html#PR-COM","s":"Commercial specialists who set the contract terms for data ownership, metadata, quality and exit."},{"t":"Data perspective","k":"Perspective","u":"perspectives.html#L-DATA","s":"The policy's home lens: identify, describe, own and improve critical data assets, and report them."},{"t":"Digital and service perspective","k":"Perspective","u":"perspectives.html#L-DIGI","s":"Services create, change and consume critical data. Service teams decide what is collected, how it is validated and what users see."},{"t":"Cyber and security perspective","k":"Perspective","u":"perspectives.html#L-CYBER","s":"Critical data assets are among the things most worth protecting. Security teams need to know which they are, and data teams need to know an asset can be recover"},{"t":"Technology and architecture perspective","k":"Perspective","u":"perspectives.html#L-TECH","s":"Platforms, integration and tooling decide whether critical data can be found, joined, checked and moved. Architecture choices made now set the cost of the next "},{"t":"Commercial and suppliers perspective","k":"Perspective","u":"perspectives.html#L-COMM","s":"Many critical assets are held or processed by suppliers, and most tools are bought. Contracts decide who owns the data, what metadata and quality evidence the s"},{"t":"Legacy and technical debt perspective","k":"Perspective","u":"perspectives.html#L-LEGACY","s":"Legacy systems concentrate critical data that is hard to find, understand or trust, and that blocks better services. Getting data out safely, and not creating t"},{"t":"CH-01 Put data assets in the business case","k":"Delivery and change (Change)","u":"change.html#CH-01","s":"The policy says data must be valued and invested in; business cases are where that money is decided."},{"t":"CH-02 Use spend control and service assessments as checkpoints","k":"Delivery and change (Change)","u":"change.html#CH-02","s":"Spend control and service assessments already stop work that is not ready; adding DAM evidence costs little."},{"t":"CH-03 Write DAM into programme assurance","k":"Delivery and change (Change)","u":"change.html#CH-03","s":"Large programmes have integrated assurance plans; DAM checks in them are reviewed with everything else."},{"t":"CH-04 Plan legacy exits from the asset register","k":"Delivery and change (Change)","u":"change.html#CH-04","s":"Legacy systems hold large concentrations of hard-to-reach data; the legacy guidance asks for an asset register first."},{"t":"CH-05 Target legacy where it blocks outcomes and widens inequalities","k":"Delivery and change (Both)","u":"change.html#CH-05","s":"Where poor or locked-in data delays access to services, the people most affected are often those already disadvantaged."},{"t":"CH-06 Build DAM into contracts","k":"Delivery and change (Both)","u":"change.html#CH-06","s":"Suppliers often hold or process critical assets; without contract terms the owner cannot meet the policy."},{"t":"CH-07 Manage data asset risk on the same registers","k":"Delivery and change (Both)","u":"change.html#CH-07","s":"The policy relies on risk controls; separate data risk lists are easy to ignore."},{"t":"CH-08 Hand over to business as usual","k":"Delivery and change (Change)","u":"change.html#CH-08","s":"Assets created by projects lose their owner when the project closes unless handover is planned."},{"t":"CH-09 Plan people change, not just process change","k":"Delivery and change (Both)","u":"change.html#CH-09","s":"New duties fail when people are not told, trained, given time or recognised for them."},{"t":"CH-10 Show the benefits","k":"Delivery and change (Both)","u":"change.html#CH-10","s":"Continued funding depends on evidence that the work changed something."},{"t":"CH-11 Keep the yearly cycle running in business as usual","k":"Delivery and change (BAU)","u":"change.html#CH-11","s":"The policy is annual; without a calendar it becomes a scramble before each return."},{"t":"CH-12 Assess maturity and set a target","k":"Delivery and change (BAU)","u":"change.html#CH-12","s":"A shared maturity measure turns the policy into a plan that can be resourced and tracked."},{"t":"CH-13 Share and reuse safely across organisations","k":"Delivery and change (Both)","u":"change.html#CH-13","s":"Reuse is the point of the policy, but it never removes legal duties or forces sharing."},{"t":"CH-14 Design out future legacy and lock-in","k":"Delivery and change (Change)","u":"change.html#CH-14","s":"Systems bought or built today become tomorrow's legacy unless their data can be moved out without loss or delay."},{"t":"CH-15 Prepare for a cyber incident affecting a critical asset","k":"Delivery and change (BAU)","u":"change.html#CH-15","s":"A ransomware attack or breach can corrupt or expose a critical asset; quality plans and owners must be ready."},{"t":"CH-16 Use the buying routes and contract terms that protect data","k":"Delivery and change (Change)","u":"change.html#CH-16","s":"Most catalogue, quality and platform tools are bought; the route and terms decide who controls the data."},{"t":"Rank critical assets by what they make possible","k":"Capability playbook activity","u":"capabilities.html#STR-1","s":"You can say which critical assets matter most and why, in one page."},{"t":"Put the ranking into the data strategy","k":"Capability playbook activity","u":"capabilities.html#STR-2","s":"The data strategy names the assets it depends on and the outcomes they serve."},{"t":"Re-rank every year with the return","k":"Capability playbook activity","u":"capabilities.html#STR-3","s":"Priorities follow what changed, not what was decided once."},{"t":"Critical data asset prioritisation scorecard","k":"Capability playbook template","u":"capabilities.html#T-STR-1","s":"Asset identifier Asset title Reuse value (1 to 5) Outcomes supported People affected Effect on inequality if it fails Legacy or technical debt risk (1 to 5) Qua"},{"t":"Map the tools you have against what the policy needs","k":"Capability playbook activity","u":"capabilities.html#TOOL-1","s":"You know which capabilities your tools cover, which they miss and when contracts end."},{"t":"Run a request for information with ready-made requirements","k":"Capability playbook activity","u":"capabilities.html#TOOL-2","s":"Suppliers answer the same questions, so answers can be compared."},{"t":"Prove it with your own data before you sign","k":"Capability playbook activity","u":"capabilities.html#TOOL-3","s":"The tool does what the supplier says, with your data and your other tools."},{"t":"Check before every renewal","k":"Capability playbook activity","u":"capabilities.html#TOOL-4","s":"You can still leave, and the tool still meets the policy."},{"t":"Tool requirements schedule","k":"Capability playbook template","u":"capabilities.html#T-PRC-1","s":"Functional requirements: Requirement ID Functional requirements: Kind of tool Functional requirements: Requirement Functional requirements: Priority (MoSCoW) Fu"},{"t":"Request for information response form","k":"Capability playbook template","u":"capabilities.html#T-PRC-2","s":"Section Question ID Question Supplier answer Meets now or partly or roadmap (with date) or no Evidence offered Clarification asked Score (0 to 4) Evaluator note"},{"t":"Evaluation and moderation sheet","k":"Capability playbook template","u":"capabilities.html#T-PRC-3","s":"Supplier Requirement ID Priority (MoSCoW) Must met (pass or fail) Evaluator 1 score Evaluator 2 score Moderated score Weight Weighted score Reason for moderated"},{"t":"Proof of concept test log","k":"Capability playbook template","u":"capabilities.html#T-PRC-4","s":"Test ID Requirement ID Test carried out Data used (test copy) Expected result Actual result Pass or fail Content lost on export Tested by (role) Date Evidence l"},{"t":"Record the main risk to each critical asset","k":"Capability playbook activity","u":"capabilities.html#RISK-1","s":"Every critical asset has at least one risk on a register someone reviews."},{"t":"Set risk appetite for data","k":"Capability playbook activity","u":"capabilities.html#RISK-2","s":"Owners know how much risk they can accept and when to escalate."},{"t":"Review data risks with the asset review","k":"Capability playbook activity","u":"capabilities.html#RISK-3","s":"Risks stay current as assets and systems change."},{"t":"Data risk register entry","k":"Capability playbook template","u":"capabilities.html#T-RSK-1","s":"Risk ID Asset identifier Risk (cause, event, effect) Kind (availability, accuracy, privacy, security, retention, supplier) Risk owner (role) Likelihood Impact S"},{"t":"Find the critical assets held or supplied by third parties","k":"Capability playbook activity","u":"capabilities.html#SUPP-1","s":"You know which critical assets depend on a supplier, and on which contract."},{"t":"Put data terms in every new contract","k":"Capability playbook activity","u":"capabilities.html#SUPP-2","s":"New contracts protect critical data from the start."},{"t":"Test the return of data before contracts end","k":"Capability playbook activity","u":"capabilities.html#SUPP-3","s":"Data comes back complete when a contract ends."},{"t":"Third-party data register entry","k":"Capability playbook template","u":"capabilities.html#T-SUP-1","s":"Asset identifier Supplier Role (holds, processes, provides) Contract reference Contract end date Data ownership stated (yes or no) Data processing schedule in p"},{"t":"Check what each data role needs to know","k":"Capability playbook activity","u":"capabilities.html#SKILL-1","s":"Everyone named in a data role knows what is expected of them."},{"t":"Build data roles into jobs and objectives","k":"Capability playbook activity","u":"capabilities.html#SKILL-2","s":"Data roles are part of the job, not extra to it."},{"t":"Keep a community of practice going","k":"Capability playbook activity","u":"capabilities.html#SKILL-3","s":"People in data roles learn from each other, inside and across organisations."},{"t":"Data role skills assessment and learning plan","k":"Capability playbook template","u":"capabilities.html#T-SKL-1","s":"Person (role in published copies) Data role Learning outcome Self-rating (1 to 4) Gap Module or course Due date Completed date Line manager agreed (yes or no)"},{"t":"Find out who uses each critical asset and what gets in their way","k":"Capability playbook activity","u":"capabilities.html#CULT-1","s":"Owners know their users and their main problems."},{"t":"Tell people what changed because of their feedback","k":"Capability playbook activity","u":"capabilities.html#CULT-2","s":"Users see that raising a problem leads to a fix."},{"t":"Make data work visible to leaders","k":"Capability playbook activity","u":"capabilities.html#CULT-3","s":"Leaders ask about data assets as they ask about money and people."},{"t":"Data user feedback log","k":"Capability playbook template","u":"capabilities.html#T-ENG-1","s":"Date Asset identifier User group Problem or request Effect on their work Owner (role) Action Status Response sent (date)"},{"t":"Take a baseline","k":"Capability playbook activity","u":"capabilities.html#MAT-1","s":"You know your starting level for each strand of data asset management."},{"t":"Set targets and an improvement plan","k":"Capability playbook activity","u":"capabilities.html#MAT-2","s":"Each strand has a target level, a date and the actions to reach it."},{"t":"Reassess every year","k":"Capability playbook activity","u":"capabilities.html#MAT-3","s":"Progress is measured, not assumed."},{"t":"Maturity baseline and improvement plan","k":"Capability playbook template","u":"capabilities.html#T-MAT-1","s":"Strand Baseline level Evidence for baseline Target level Target date Actions (playbook activity IDs) Action owner (role) Checkpoint level at 6 months Checkpoint"},{"t":"Name the critical assets in every business case","k":"Capability playbook activity","u":"capabilities.html#INV-1","s":"Business cases say which critical assets they create, change or depend on."},{"t":"Make the case for investing in data assets","k":"Capability playbook activity","u":"capabilities.html#INV-2","s":"Investment in data assets is argued with costs, benefits and the cost of doing nothing."},{"t":"Fund the yearly cycle in business as usual","k":"Capability playbook activity","u":"capabilities.html#INV-3","s":"The annual review, catalogue and quality work have a budget that does not end with a project."},{"t":"Data assets section for a business case","k":"Capability playbook template","u":"capabilities.html#T-INV-1","s":"Asset identifier Asset title Created or changed or depends on Owner (role) Catalogue record Current cost of the problem Benefit expected Measure Baseline Target"},{"t":"Add data asset questions to existing checkpoints","k":"Capability playbook activity","u":"capabilities.html#ASSR-1","s":"Spend control, gate reviews and service assessments ask about critical data."},{"t":"Put data checkpoints into the assurance plan","k":"Capability playbook activity","u":"capabilities.html#ASSR-2","s":"Large programmes plan their data assurance from the start."},{"t":"Learn from checkpoint findings","k":"Capability playbook activity","u":"capabilities.html#ASSR-3","s":"Common problems are fixed in guidance, not found again and again."},{"t":"Data asset checkpoint questions","k":"Capability playbook template","u":"capabilities.html#T-ASR-1","s":"Checkpoint (spend control or gate or service assessment) Programme Critical assets created or changed or retired Owner named for each (yes or no) Catalogue reco"},{"t":"List the critical assets in each legacy system","k":"Capability playbook activity","u":"capabilities.html#LEG-1","s":"You know what data each legacy system holds before anyone plans to replace it."},{"t":"Migrate with reconciliation","k":"Capability playbook activity","u":"capabilities.html#LEG-2","s":"Data arrives complete and correct, and you can prove it."},{"t":"Switch off safely","k":"Capability playbook activity","u":"capabilities.html#LEG-3","s":"Nothing needed is lost when a system is turned off."},{"t":"Legacy exit and migration plan","k":"Capability playbook template","u":"capabilities.html#T-LEG-1","s":"Assets in the system: Asset identifier Assets in the system: Asset title Assets in the system: Owner (role) Assets in the system: Downstream dependants Assets i"},{"t":"Name the business-as-usual owner early","k":"Capability playbook activity","u":"capabilities.html#HAND-1","s":"Every asset a project creates has an owner who will be there after the project."},{"t":"Hand over with a checklist","k":"Capability playbook activity","u":"capabilities.html#HAND-2","s":"Business as usual receives everything needed to run the asset."},{"t":"Check six months after handover","k":"Capability playbook activity","u":"capabilities.html#HAND-3","s":"The asset is still owned, catalogued and checked after the project team has gone."},{"t":"Handover to business as usual checklist","k":"Capability playbook template","u":"capabilities.html#T-HND-1","s":"Asset identifier Business-as-usual owner (role) Steward (role) Catalogue record current (yes or no) Quality plan in place (yes or no) Risks transferred (yes or "},{"t":"Pick a few measures and record the baseline","k":"Capability playbook activity","u":"capabilities.html#BEN-1","s":"You can show change, because you know where you started."},{"t":"Track and report the benefits","k":"Capability playbook activity","u":"capabilities.html#BEN-2","s":"Leaders see progress against the baseline each quarter."},{"t":"Evaluate after a year","k":"Capability playbook activity","u":"capabilities.html#BEN-3","s":"You know what worked, what did not and why."},{"t":"Benefits register","k":"Capability playbook template","u":"capabilities.html#T-BEN-1","s":"Benefit ID Benefit Measure How measured Baseline Baseline date Target Target date Measurement frequency Latest value Benefit owner (role) Assets involved Notes"},{"t":"Ask three questions of every new system","k":"Capability playbook activity","u":"capabilities.html#EXIT-1","s":"No new system holds critical data you cannot get out."},{"t":"Write and cost the exit plan","k":"Capability playbook activity","u":"capabilities.html#EXIT-2","s":"Leaving is planned and costed before you sign."},{"t":"Test the exit every year","k":"Capability playbook activity","u":"capabilities.html#EXIT-3","s":"The exit plan still works."},{"t":"Exit and portability plan","k":"Capability playbook template","u":"capabilities.html#T-EXT-1","s":"System Critical assets held Export formats Schema published (location) Last full export test Content lost in test Steps to exit Time to exit Cost to exit In con"},{"t":"Capability plan for the first year","k":"Leader route template","u":"leading.html#T-LDR-1","s":"Aims: Priority (MoSCoW) Aims: Aim Aims: Outcome Aims: Capabilities Aims: Owner (role) Outcomes and targets: Outcome ID Outcomes and targets: Outcome Outcomes an"},{"t":"Checkpoint review record","k":"Leader route template","u":"leading.html#T-LDR-2","s":"Checkpoint Date Strand Level at last checkpoint Level now Evidence What worked What did not Decision (continue or change or stop) Actions Owner (role) Reviewed "},{"t":"First 30 days","k":"Leader route checkpoint","u":"leading.html#d30","s":"Learn, listen and find out where you are. Read the DAM Policy page and the guide for your role. Meet the chief data officer, the board chair and a few owners an"},{"t":"Days 31 to 60","k":"Leader route checkpoint","u":"leading.html#d60","s":"Agree what to aim for and who does what. Rank critical assets with the prioritisation scorecard and agree the top ten with the board. Agree your Must, Should an"},{"t":"Days 61 to 90","k":"Leader route checkpoint","u":"leading.html#d90","s":"Start the cycle on the assets that matter most. Complete catalogue records for the top ten. Start a data quality action plan for each of the top ten. Add the th"},{"t":"Six-month checkpoint","k":"Leader route checkpoint","u":"leading.html#m6","s":"Check progress and fix what is stuck. Reassess against the baseline, strand by strand. Extend ownership and catalogue records to all critical assets. Report ben"},{"t":"Twelve-month checkpoint","k":"Leader route checkpoint","u":"leading.html#m12","s":"Meet the policy and make the cycle routine. Submit a complete, on-time return. Reassess maturity and reset targets for the next year. Re-rank critical assets an"},{"t":"BL-01 Private feedback route","k":"Backlog","u":"research.html#bl-BL-01","s":"As someone without a GitHub account, I need a private way to give feedback, so that I can take part without publishing my views."},{"t":"BL-02 Share, site map, guided tours and tutorials","k":"Backlog","u":"research.html#bl-BL-02","s":"As a first-time visitor, I need to see how the portal fits together, so that I can find my way without help."},{"t":"BL-03 Signposts to the sister portals","k":"Backlog","u":"research.html#bl-BL-03","s":"As a practitioner, I need to know when another portal goes deeper, so that I do not miss tools or evidence."},{"t":"BL-04 Data portals compass","k":"Backlog","u":"research.html#bl-BL-04","s":"As someone working across policy, practice and technology, I need to know where to start and in what order, so that I take the shortest route to a result."},{"t":"BL-05 Research, roadmap and ideas in the open","k":"Backlog","u":"research.html#bl-BL-05","s":"As a user, I need to see what is planned and how decisions are made, and to suggest and vote for ideas, so that the portal meets real needs."},{"t":"BL-10 Round 1: can each role find and follow its steps?","k":"Backlog","u":"research.html#bl-BL-10","s":"As the service owner, I need evidence from 5 to 8 people per role, so that changes rest on what users do, not what we assume."},{"t":"BL-11 Test with disabled people and assistive technology","k":"Backlog","u":"research.html#bl-BL-11","s":"As someone who uses a screen reader, magnifier or voice control, I need the portal to work with my set-up, so that I can follow the policy like anyone else."},{"t":"BL-12 Private research sign-up form","k":"Backlog","u":"research.html#bl-BL-12","s":"As a prospective participant, I need to sign up privately, so that my contact details are not published."},{"t":"BL-13 Round 0: introduce the portal and recruit participants","k":"Backlog","u":"research.html#bl-BL-13","s":"As the service owner, I need a pool of participants from every role, organisation type and nation, so that research rounds can start quickly."},{"t":"BL-14 Expert review of the sector supplements","k":"Backlog","u":"research.html#bl-BL-14","s":"As a sector specialist, I need the supplements checked by people who know the sector, so that I can trust them."},{"t":"BL-15 Check this flag","k":"Backlog","u":"research.html#bl-BL-15","s":"As a policy coordinator, I need to tell you when a capability flag looks wrong, so that the capability model stays accurate."},{"t":"BL-16 Embed a step or table on an intranet","k":"Backlog","u":"research.html#bl-BL-16","s":"As a department's data team, I need to show one policy step or table on our intranet, so that colleagues see it where they work."},{"t":"BL-17 Level labels and easy read summaries","k":"Backlog","u":"research.html#bl-BL-17","s":"As someone new to data management, I need to know which pages are pitched at me and to read short plain summaries, so that I am not put off."},{"t":"BL-18 Ask questions answered from the portal","k":"Backlog","u":"research.html#bl-BL-18","s":"As a busy reader, I need to ask a question in my own words and get the page that answers it, so that I do not have to know where things are."},{"t":"BL-19 Releases feed","k":"Backlog","u":"research.html#bl-BL-19","s":"As a returning user, I need to know when something changes, so that I keep up without checking the site."},{"t":"BL-20 Lineage and ontology downloads","k":"Backlog","u":"research.html#bl-BL-20","s":"As a metadata specialist, I need the requirement-to-check lineage and the ontology in open formats, so that I can reuse them in our tools."},{"t":"BL-21 Offline copy","k":"Backlog","u":"research.html#bl-BL-21","s":"As someone whose network blocks GitHub Pages, I need a copy I can open offline, so that I can still use the guidance."},{"t":"BL-22 Clearance and an official home","k":"Backlog","u":"research.html#bl-BL-22","s":"As a department, I need to know whether this is guidance I can rely on, so that I can use it in my organisation."},{"t":"BL-23 Agreed metadata terms for the four missing properties","k":"Backlog","u":"research.html#bl-BL-23","s":"As a catalogue manager, I need agreed terms for every required property, so that our records match everyone else's."},{"t":"BL-24 Welsh language needs","k":"Backlog","u":"research.html#bl-BL-24","s":"As someone in a Welsh public body, I may need the portal in Welsh, so that we can meet our language duties."},{"t":"BL-26 Boards, councils and networks","k":"Backlog","u":"research.html#bl-BL-26","s":"As a data leader, I need to know which boards decide, which advise and where practitioners meet, so that I can take issues to the right place."},{"t":"BL-27 Get involved and champions toolkit","k":"Backlog","u":"research.html#bl-BL-27","s":"As a champion in my organisation, I need ready-made posts, emails and a walk-through, so that I can bring my team in without extra work."},{"t":"BL-28 Badges for taking part","k":"Backlog","u":"research.html#bl-BL-28","s":"As someone who helps improve the portal, I want a badge for my profile and signature, so that my contribution is recognised."},{"t":"BL-29 Welsh language summaries","k":"Backlog","u":"research.html#bl-BL-29","s":"As someone in a Welsh public body, I need key pages summarised in Welsh, so that we can meet our language duties."},{"t":"BL-30 Governance layers and what each may change","k":"Backlog","u":"research.html#bl-BL-30","s":"As a data owner, I need to know what each governance layer may and may not change, so that decisions go to the right place and survive a team handover."},{"t":"BL-31 Retention fields in the ownership register and catalogue record","k":"Backlog","u":"research.html#bl-BL-31","s":"As a data owner, I need retention and disposal recorded with each asset, so that data is neither kept too long nor destroyed early."},{"t":"BL-32 Data sharing agreement template and gateways","k":"Backlog","u":"research.html#bl-BL-32","s":"As a data owner, I need a data sharing agreement that covers the lawful basis and legal gateway, so that shared critical assets are on a sound footing."},{"t":"BL-33 Data architecture and models supplement","k":"Backlog","u":"research.html#bl-BL-33","s":"As a data architect, I need to describe a critical asset's entities, relationships and authoritative source, so that others can build on it and returns do not c"},{"t":"BL-34 Health and care obligations from DHSC and MedTech","k":"Backlog","u":"research.html#bl-BL-34","s":"As a health or care body, I need the laws, standards and frameworks that apply to our data assets in one place, so that we meet them alongside the DAM Policy."},{"t":"BL-35 Drill down from the DAMA wheel to activities and tasks","k":"Backlog","u":"research.html#bl-BL-35","s":"As someone building an enterprise data management capability, I need to go from a knowledge area on the wheel to its activities and tasks, so that I can see wha"},{"t":"BL-36 Data architecture capability playbook","k":"Backlog","u":"research.html#bl-BL-36","s":"As a data architect or design authority, I need a step-by-step playbook for data architecture, so that critical assets have a known structure and authoritative "},{"t":"BL-25 A chatbot hosted by this portal","k":"Backlog","u":"research.html#bl-BL-25","s":"As a reader, I would like to chat with the guidance."},{"t":"Chief Data Officer (CDO) Council","k":"Board or network","u":"bodies.html#GB-CDO","s":"The decision-making body overseeing strategic delivery of Mission 3 of the National Data Strategy (government's own use of data)."},{"t":"Data Standards Authority (DSA) Steering Board","k":"Board or network","u":"bodies.html#GB-DSASB","s":"A senior advisory group that supports the Data Standards Authority in setting cross-government data standardisation strategy and delivery plans."},{"t":"Peer Review Group for the DSA and the Data Quality Hub","k":"Board or network","u":"bodies.html#GB-PRG","s":"Reviews products, proposals and standards before they go to the DSA Steering Board, and reviews products from the Government Data Quality Hub."},{"t":"Open Standards Board","k":"Board or network","u":"bodies.html#GB-OSB","s":"Accountable for the transparent selection and implementation of open standards for government."},{"t":"Data and Technology Architecture Design Authority (DTADA)","k":"Board or network","u":"bodies.html#GB-DTADA","s":"The decision-making body for data architecture principles, policies, strategies and standards."},{"t":"Taxonomy Oversight Group","k":"Board or network","u":"bodies.html#GB-TOG","s":"Coordinates taxonomy work across government and recommends taxonomies for common use."},{"t":"Data Steering Group","k":"Board or network","u":"bodies.html#GB-DSG","s":"Strategic oversight of the use and management of government's data, inside and outside the public sector."},{"t":"Data Management Community","k":"Board or network","u":"bodies.html#NW-DMC","s":"A cross-government network sharing practice on data quality, metadata, governance and data catalogues. It also maintains the DAM Policy."},{"t":"Government Data Quality Community","k":"Board or network","u":"bodies.html#NW-GDQC","s":"A place for public sector data professionals to meet, share and learn about data quality, launched in 2022."},{"t":"Data Sharing Network of Experts","k":"Board or network","u":"bodies.html#NW-DSNE","s":"Impartial advice to unblock data sharing, bringing together data protection, governance, security, privacy and policy specialists."},{"t":"Government Data Architecture Community","k":"Board or network","u":"bodies.html#NW-GDAC","s":"A cross-government community of data architects; it includes the Taxonomy Oversight Group."},{"t":"API and data exchange community","k":"Board or network","u":"bodies.html#NW-API","s":"Shares knowledge and practice on APIs and interoperability, with monthly meetings and expert speakers."},{"t":"Data and AI ethics community","k":"Board or network","u":"bodies.html#NW-ETH","s":"Discusses the ethical use of data, AI and technology in government, with events on transparency, trust and fairness."},{"t":"Data engineering community","k":"Board or network","u":"bodies.html#NW-DENG","s":"Supports people designing data products, automating data processes and applying data standards and models."},{"t":"Government Statistical Service quality champions","k":"Board or network","u":"bodies.html#NW-QCH","s":"Departmental quality champions who support statistical heads of profession, meeting monthly."},{"t":"Data Linkage Champions Network","k":"Board or network","u":"bodies.html#NW-DLCN","s":"A methodological network supporting colleagues involved in data linkage at all levels."},{"t":"Data communities newsletter","k":"Board or network","u":"bodies.html#NW-NEWS","s":"A monthly newsletter with news, events, learning and community updates for public sector data professionals."},{"t":"Map where each critical asset lives","k":"Knowledge area activity","u":"areas.html#ARC-1","s":"One list that says which systems hold each critical asset, so nothing is designated from the wrong copy."},{"t":"Name the authoritative source for each critical asset","k":"Knowledge area activity","u":"areas.html#ARC-2","s":"Everyone who reuses the asset knows which copy to trust and where to report problems."},{"t":"Draw the main data flows between systems and organisations","k":"Knowledge area activity","u":"areas.html#ARC-3","s":"You can say where critical data goes, so sharing, quality and security risks have a place on the map."},{"t":"Set a target data architecture and record decisions","k":"Knowledge area activity","u":"areas.html#ARC-4","s":"Changes move critical assets toward open, portable designs instead of new legacy."},{"t":"Make architecture review a gate in change","k":"Knowledge area activity","u":"areas.html#ARC-5","s":"Every change that touches a critical asset updates its landscape, source and flows before it goes live."},{"t":"List the entities and relationships in each critical asset","k":"Knowledge area activity","u":"areas.html#MOD-1","s":"A plain list of what the asset is about (people, cases, payments, places) and how they connect."},{"t":"Agree definitions for the attributes people rely on","k":"Knowledge area activity","u":"areas.html#MOD-2","s":"The same word means the same thing in every system and report that uses the asset."},{"t":"Publish a data dictionary with the catalogue record","k":"Knowledge area activity","u":"areas.html#MOD-3","s":"Users can see the columns, types and allowed values before they ask for access."},{"t":"Control changes to models","k":"Knowledge area activity","u":"areas.html#MOD-4","s":"A change to structure never breaks reports, sharing or quality rules without warning."},{"t":"Name the custodian and hosting for each critical asset","k":"Knowledge area activity","u":"areas.html#OPS-1","s":"Someone is responsible for keeping each asset running, and you know where it is hosted."},{"t":"Back up critical assets and test that you can restore them","k":"Knowledge area activity","u":"areas.html#OPS-2","s":"A failure or attack does not lose critical data or the service that depends on it."},{"t":"Monitor availability, freshness and capacity","k":"Knowledge area activity","u":"areas.html#OPS-3","s":"Problems are found by the custodian before users find them."},{"t":"Plan retention, archiving and decommissioning","k":"Knowledge area activity","u":"areas.html#OPS-4","s":"Data is kept as long as needed and no longer, and nothing critical is lost when a system retires."},{"t":"Record classification and personal data for each asset","k":"Knowledge area activity","u":"areas.html#SEC-1","s":"Every catalogue record says how the asset is classified and whether it holds personal data."},{"t":"Record who can access each asset, and on what basis","k":"Knowledge area activity","u":"areas.html#SEC-2","s":"People asking for data can see the route and the conditions without starting from scratch."},{"t":"Link critical assets to cyber risk","k":"Knowledge area activity","u":"areas.html#SEC-3","s":"Security effort goes first to the data that matters most."},{"t":"Make data incidents reach owners and quality leads","k":"Knowledge area activity","u":"areas.html#SEC-4","s":"A breach or corruption of critical data is handled as a data problem as well as a security one."},{"t":"Record which critical assets depend on encryption, and where they are stored","k":"Knowledge area activity","u":"areas.html#SEC-5","s":"When encryption or data residency rules change, you can find the affected assets by a search, not a survey."},{"t":"Use the identifiers and standards government expects","k":"Knowledge area activity","u":"areas.html#INT-1","s":"Your critical assets can be matched with others without guesswork."},{"t":"Classify and crosswalk the standards each asset meets","k":"Knowledge area activity","u":"areas.html#INT-2","s":"Anyone can see which standards an asset meets, and how your terms map to them, in a form machines can read."},{"t":"Share critical data through documented interfaces","k":"Knowledge area activity","u":"areas.html#INT-3","s":"Other teams reuse the authoritative source, not a copy made for one project."},{"t":"Agree data contracts and record lineage","k":"Knowledge area activity","u":"areas.html#INT-4","s":"Producers and consumers know what to expect, and anyone can trace a figure back to its source."},{"t":"Check which critical assets are also public records","k":"Knowledge area activity","u":"areas.html#DOC-1","s":"Records managers and data owners work from the same list."},{"t":"Attach retention and disposal to each catalogue record","k":"Knowledge area activity","u":"areas.html#DOC-2","s":"Users can see how long data is kept and what happens to it next."},{"t":"Transfer, archive or destroy with evidence","k":"Knowledge area activity","u":"areas.html#DOC-3","s":"Disposal is lawful, recorded and reflected in the catalogue."},{"t":"Find the reference data each critical asset depends on","k":"Knowledge area activity","u":"areas.html#REF-1","s":"You know which code lists each asset uses and where they come from."},{"t":"Use shared controlled vocabularies, not local copies","k":"Knowledge area activity","u":"areas.html#REF-2","s":"Fewer local lists, so data joins across services without mapping by hand."},{"t":"Name a master record for shared entities","k":"Knowledge area activity","u":"areas.html#REF-3","s":"People, organisations and places are recorded once and matched consistently."},{"t":"Find peers before you buy or build","k":"Knowledge area activity","u":"areas.html#REF-5","s":"You learn from public bodies that already run the tool or keep the list, before you commit."},{"t":"Choose a master data tool with exit in mind","k":"Knowledge area activity","u":"areas.html#REF-6","s":"The tool fits how you run services, and your master data can leave it."},{"t":"Publish shared lists as open, versioned data","k":"Knowledge area activity","u":"areas.html#REF-7","s":"Others reuse your list instead of copying it, and every copy can tell when it is out of date."},{"t":"Govern changes to code lists","k":"Knowledge area activity","u":"areas.html#REF-4","s":"A change to a code list never silently breaks a report or a share."},{"t":"List the reports and statistics that use each critical asset","k":"Knowledge area activity","u":"areas.html#BI-1","s":"You can show who relies on the asset, which supports its designation and its priority."},{"t":"Show quality and provenance next to published figures","k":"Knowledge area activity","u":"areas.html#BI-2","s":"People reading a figure know how good the data behind it is."},{"t":"Make analytical copies traceable to their source","k":"Knowledge area activity","u":"areas.html#BI-3","s":"Every warehouse table or extract can be traced back to its critical asset."},{"t":"Measure the value and reuse of critical assets","k":"Knowledge area activity","u":"areas.html#BI-4","s":"The annual review knows which assets earn their keep and which need investment."},{"t":"Govern a business glossary","k":"Knowledge area activity","u":"areas.html#META-1","s":"Each important term has one agreed meaning, an owner and a history."},{"t":"Climb from glossary to knowledge graph","k":"Knowledge area activity","u":"areas.html#META-2","s":"Your terms, standards, assets and owners become linked data that people, catalogues and AI tools can query."},{"t":"Make critical assets ready for AI","k":"Knowledge area activity","u":"areas.html#DQ-AI","s":"Critical assets can be used by AI tools safely, with known quality, meaning and limits."}];
window.DCP_MODULES={"M01":["M01.a1","M01.a2","M01.a3","M01.a4"],"M02":["M02.a1","M02.a2","M02.a3","M02.a4"],"M03":["M03.a1","M03.a2","M03.a3","M03.a4"],"M04":["M04.a1","M04.a2","M04.a3","M04.a4"],"M05":["M05.a1","M05.a2","M05.a3","M05.a4"],"M06":["M06.a1","M06.a2","M06.a3"],"M07":["M07.a1","M07.a2","M07.a3"],"M08":["M08.a1","M08.a2","M08.a3","M08.a4"],"M09":["M09.a1","M09.a2","M09.a3"],"M10":["M10.a1","M10.a2","M10.a3"],"M11":["M11.a1","M11.a2","M11.a3","M11.a4"],"M12":["M12.a1","M12.a2","M12.a3","M12.a4"],"M13":["M13.a1","M13.a2","M13.a3","M13.a4","M13.a5"],"M14":["M14.a1","M14.a2","M14.a3","M14.a4","M14.a5"],"M15":["M15.a1","M15.a2","M15.a3","M15.a4","M15.a5","M15.a6"],"M16":["M16.a1","M16.a2","M16.a3","M16.a4","M16.a5"],"M17":["M17.a1","M17.a2","M17.a3","M17.a4","M17.a5","M17.a6"],"M18":["M18.a1","M18.a2","M18.a3","M18.a4"],"M19":["M19.a1","M19.a2","M19.a3","M19.a4"]};
window.DCP_MODINFO={"M01":{"t":"The DAM Policy - what it asks of you","l":"Foundation","m":15,"o":["Explain who the policy applies to and what is in scope","Name the core duties: identify and catalogue assets, report them, name an owner and manage quality","Find the requirement behind any step in these playbooks"]},"M02":{"t":"Roles and accountability","l":"Foundation","m":15,"o":["Describe the data owner, data steward and data custodian roles","Explain how the data owner relates to the information asset owner","Choose between the three ownership options"]},"M03":{"t":"Setting up governance with five recipes","l":"Practitioner","m":30,"o":["Run the Mandate, Frame, Assign, Operate and Assure recipes in order","Set up a decision log and an exception register","Collect evidence continuously for the GDS return"]},"M04":{"t":"Finding and designating critical data assets","l":"Practitioner","m":25,"o":["Build a candidate list from existing registers","Apply the scope tests and the seven purposes","Draw an asset's boundary and record why"]},"M05":{"t":"Describing assets with metadata others can use","l":"Practitioner","m":30,"o":["Record the metadata properties in the GOV.UK guidance","Write titles and descriptions in plain English","Map properties to the Metadata Exchange Model"]},"M06":{"t":"Cataloguing, harvesting and reporting to GDS","l":"Practitioner","m":20,"o":["Expose records so others can harvest them","Produce the return from catalogue records","Plan the annual review"]},"M07":{"t":"Data quality foundations","l":"Foundation","m":15,"o":["Name the five principles and six dimensions of the Government Data Quality Framework","Explain what a DQAP is for","Recognise when quality differs between groups of people"]},"M08":{"t":"Building a DQAP and scoring issues","l":"Practitioner","m":35,"o":["Write rules with targets from the issues framework","Measure a baseline and log issues","Prioritise issues and set resolution dates"]},"M09":{"t":"Running the three capabilities as one yearly cycle","l":"Advanced","m":20,"o":["Use the hand-offs so each fact is recorded once","Plan one annual review per asset","Feed assurance lessons into the next mandate"]},"M10":{"t":"Inclusive data practice","l":"Foundation","m":20,"o":["Apply equality and inclusion checks in each capability","Make data quality statements and records accessible","Involve people the data describes"]},"M11":{"t":"Embedding the policy in delivery and change","l":"Practitioner","m":30,"o":["Name the capabilities the policy relies on but does not state","Build DAM checkpoints into a business case and an assurance plan","Plan a legacy exit and a handover to business as usual"]},"M12":{"t":"What makes a critical data asset AI-ready","l":"Foundation","m":20,"o":["Name the four pillars in the GDS guidelines on AI-ready datasets","Decide whether an asset needs the AI-ready supplement","Explain why AI-readiness is a stewardship question as well as a technical one"]},"M13":{"t":"From FAIR to AI-ready metadata","l":"Practitioner","m":30,"o":["Explain the four FAIR principles in plain English","Add the AI-ready catalogue fields to a record","See how the proposed DCAT-AP-UK profile extends the xGov MEM for AI use"]},"M14":{"t":"Start from the question the data must answer","l":"Practitioner","m":20,"o":["Write down the decision or question an AI use of an asset serves","Test that question against the seven purposes in the policy","Record out-of-scope uses before anyone asks for them"]},"M15":{"t":"Connecting data to AI with linked data, knowledge graphs and MCP","l":"Advanced","m":35,"o":["Explain the RDF triple and why linked data helps machines read metadata","Find and reuse this portal's knowledge graph and vocabulary files","Describe how an MCP server lets an AI assistant check metadata against the xGov MEM"]},"M16":{"t":"Making public data AI-ready together","l":"Practitioner","m":25,"o":["Look for existing work before building, across public sector code and catalogues","Involve the people the data describes when you judge whether it is fit for AI","Use the shared assurance and community routes rather than working alone"]},"M17":{"t":"Governing AI use of critical data in practice","l":"Advanced","m":30,"o":["Run the AI-ready quality rules on a sample file","Apply the transparency and ethics duties that go with AI use","Plan who monitors drift and bias once AI use begins"]},"M18":{"t":"Leading data asset management - your first year","l":"Foundation","m":25,"o":["Set Must, Should and Could aims for your organisation and the outcomes each brings","Plan the first 30, 60 and 90 days and the 6 and 12 month checkpoints","Choose the maturity model that fits each aim and measure progress against a baseline"]},"M19":{"t":"Buying tools for data asset management without lock-in","l":"Practitioner","m":30,"o":["Pick the requirements that fit the kinds of tool you need, with priorities","Run a request for information and a proof of concept with your own data","Ask for contract clauses that keep your data movable"]}};
